// Five original hard AgilePM v3 Foundation papers (21–25).
// Official APMG style + syllabus weighting. Not official APMG items.
// Lean: planning vs tracking, MbE, Project Sprint Planning, Daily Scrum
// is not vacation planning, multi-team events, PAQ timing/remedies,
// risk as a VUCA consequence.

export const FINAL_MOCKS_E = [
  {
    id: 'final21',
    title: 'Final Paper 21',
    questions: [
      { id: 'F21Q1', topic: 'KC', q: 'According to AgilePM, what must people be able to do in order to exercise agility when facing VUCA?', options: ['Follow documented procedures without deviation', 'Wait for complete information before acting', 'Escalate every uncertainty to the Business Sponsor', 'Think, assess and adapt'], correct: 'Think, assess and adapt', explain: 'Agility requires people who can think, assess and adapt, move through complex situations, and take effective action (2.1.2).' },
      { id: 'F21Q2', topic: 'KC', q: 'Identify the missing word. In extreme cases of Scientific Management, employees were treated like [ ? ].', options: ['partners', 'Product Owners', 'self-managing teams', 'machines'], correct: 'machines', explain: 'Taylorism\'s limitation was that staff acted as operators of systems; in extreme cases employees were treated like machines (2.1.2).' },
      { id: 'F21Q3', topic: 'KC', q: 'Which of the following are value statements in the Agile Manifesto as enhanced for the project context?\n1. Individuals and interactions over processes and tools\n2. Working solutions over comprehensive documentation\n3. Comprehensive contracts over customer collaboration\n4. Responding to change over following a plan', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The third value is customer collaboration over contract negotiation, not the reverse (2.1.3).' },
      { id: 'F21Q4', topic: 'KC', q: 'Consider the statements about why agility is needed in project delivery.\n1. Legacy sequential methods assume the design will stay relevant and effective from start to finish\n2. Product Lifecycle Management removes any need for project structure or governance', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Legacy methods assume the design stays relevant; PLM complements project management rather than replacing structure (2.1.2, 2.2–2.3).' },
      { id: 'F21Q5', topic: 'KC', q: 'Which statement best describes how project management differs from product development in AgilePM?', options: ['Product development organises the wider environment in which development takes place', 'Project management focuses only on the long-term evolution of a single product', 'Product development is solely about controlling investment and resources', 'Project management organises and oversees the environment so that the value of the product is actually achieved once delivered'], correct: 'Project management organises and oversees the environment so that the value of the product is actually achieved once delivered', explain: 'Product development focuses on what the product becomes; project management oversees the environment so delivered value is realised (2.2–2.3).' },
      { id: 'F21Q6', topic: 'SC', q: 'Which of the following correctly describe Scrum theory?\n1. Knowledge comes from a complete up-front specification\n2. Empiricism asserts that decisions are based on what is observed\n3. Lean thinking reduces waste and focuses on essentials\n4. Adaptation must occur as soon as possible to minimise further deviation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Scrum is founded on empiricism and lean thinking; knowledge comes from experience, not a complete up-front specification (3.2).' },
      { id: 'F21Q7', topic: 'SC', q: 'What is the single objective created during Sprint Planning that gives Developers flexibility in the exact work needed to achieve it?', options: ['The Product Goal', 'The Solution Goal', 'The Definition of Done', 'The Sprint Goal'], correct: 'The Sprint Goal', explain: 'The Sprint Goal is the single Sprint objective and a Developers\' commitment; exact work may flex around it (3.6).' },
      { id: 'F21Q8', topic: 'SC', q: 'Identify the missing word. A new Sprint starts [ ? ] after the conclusion of the previous one.', options: ['after a one-week firebreak', 'only when the Product Owner authorises it', 'once the Project Manager has approved the next plan', 'immediately'], correct: 'immediately', explain: 'Sprints are consecutive: a new Sprint starts immediately after the previous one ends (3.5).' },
      { id: 'F21Q9', topic: 'SC', q: 'Consider the statements about cancelling a Sprint.\n1. The Scrum Master may cancel a Sprint if Developers are blocked\n2. Only the Product Owner can cancel a Sprint, and only if the Sprint Goal becomes obsolete', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Cancellation is solely the Product Owner\'s decision, and only when the Sprint Goal is obsolete (3.5).' },
      { id: 'F21Q10', topic: 'SC', q: 'Which of the following correctly pair a Scrum artifact with its commitment?\n1. Product Backlog committed to the Product Goal\n2. Sprint Backlog committed to the Definition of Done\n3. Sprint Backlog committed to the Sprint Goal\n4. Increment committed to the Definition of Done', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Sprint Backlog → Sprint Goal; Increment → Definition of Done. Statement 2 pairs the Sprint Backlog with the wrong commitment (3.6).' },
      { id: 'F21Q11', topic: 'SC', q: 'If a Product Backlog item does not meet the Definition of Done by the end of the Sprint, what happens to it?', options: ['It is presented at the Sprint Review as partially complete', 'It is automatically carried into the next Sprint Backlog', 'It is deleted from the Product Backlog', 'It cannot be released or presented at the Sprint Review and returns to the Product Backlog'], correct: 'It cannot be released or presented at the Sprint Review and returns to the Product Backlog', explain: 'Undone items are not releasable or reviewable as Increment; they return to the Product Backlog (3.6).' },
      { id: 'F21Q12', topic: 'AF', q: 'In AgilePM, what does pragmatism mean as an underlying ethos?', options: ['Introducing extra process to cover every eventuality', 'Replacing the eight principles with local guidelines', 'Fixing features and flexing quality when under pressure', 'Making decisions that adapt to real-life situations rather than following rigid rules'], correct: 'Making decisions that adapt to real-life situations rather than following rigid rules', explain: 'Pragmatism means adapting decisions to real life rather than following rigid rules; common sense avoids unnecessary complexity (4.1).' },
      { id: 'F21Q13', topic: 'AF', q: 'Which of the following are AgilePM principles?\n1. Focus on the Business Need\n2. Build Incrementally from Firm Foundations\n3. Communicate Continuously and Clearly\n4. Maximise work done through overtime', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Overtime is not a principle; sustainable pace and the eight stated principles apply (4.3).' },
      { id: 'F21Q14', topic: 'AF', q: 'Identify the missing words. Under Never Compromise Quality, the solution should be [ ? ] to meet business needs, not exceeding or falling short.', options: ['technically perfect', 'fully featured', 'signed off by every stakeholder', 'fit for purpose'], correct: 'fit for purpose', explain: 'Quality is agreed up front; the solution should be good enough / fit for purpose, not more or less (4.3).' },
      { id: 'F21Q15', topic: 'AF', q: 'Consider the statements about contingency in the real world.\n1. Sponsors often hesitate to set aside formal time or budget contingency because work expands to fill the time available\n2. AgilePM therefore places contingency in the scope of features via MoSCoW rather than in time or cost', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Parkinson\'s Law and change-control friction make time/cost contingency ineffective; AgilePM flexes features instead (4.2).' },
      { id: 'F21Q16', topic: 'AF', q: 'Beyond Scrum\'s team-level product development, what additional coverage does AgilePM specifically provide for work such as business process change?', options: ['A rule that such work must be excluded from the project', 'A replacement of the Product Owner by a Process Advisor', 'A project lifecycle, extra roles and techniques that can handle business-related work not directly linked to product development', 'A requirement to treat process change as Won\'t Have this time'], correct: 'A project lifecycle, extra roles and techniques that can handle business-related work not directly linked to product development', explain: 'AgilePM with Scrum adds lifecycle, governance and roles that can manage business change Scrum alone cannot easily handle (4.4).' },
      { id: 'F21Q17', topic: 'IN', q: 'Which of the following statements correctly reflect Agile Leadership principles?\n1. Leadership lives everywhere in the organisation\n2. Command-and-control is the default agile style\n3. Leaders devolve appropriate power and authority\n4. Collaborative communities achieve more than individuals', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Agile leadership empowers self-organisation; command-and-control is not a leadership principle (5.1).' },
      { id: 'F21Q18', topic: 'IN', q: 'Which AgilePM role domain is concerned with leading the project as defined by the AgilePM approach?', options: ['Value Ownership', 'Solution Delivery', 'Delivery Enablement', 'Community Collaboration'], correct: 'Delivery Enablement', explain: 'Delivery Enablement is the Project Manager\'s domain — leading the project as defined by AgilePM (5.3).' },
      { id: 'F21Q19', topic: 'IN', q: 'Consider the statements about authority among Project Roles.\n1. The Business Sponsor, Business Visionary and Solution Architect hold the same level of authority\n2. The Project Manager holds the same level of authority as the Business Sponsor', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Equal authority sits with BS, BV and SA; the PM is empowered by the Sponsor but does not share that authority level (5.3, 5.5).' },
      { id: 'F21Q20', topic: 'IN', q: 'Identify the missing role. The Product Owner\'s four key stakeholder relationships are the Business Visionary, the Solution Architect, the Project Manager and [ ? ].', options: ['the Business Sponsor', 'the Scrum Master only', 'Business and Technical Advisors', 'external regulators only'], correct: 'Business and Technical Advisors', explain: 'The PO\'s four relationships are BV, SA, PM and Business & Technical Advisors — not the Sponsor (5.2.5).' },
      { id: 'F21Q21', topic: 'IN', q: 'Which of the following are Project Manager accountabilities in AgilePM?\n1. Managing the project environment and creating conditions for self-management\n2. Developing and maintaining high-level planning artifacts with other Project Roles\n3. Creating the Business Case and owning the project budget\n4. Acting as final authority on delivery enablement decisions', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Business Sponsor owns the Business Case and budget; the PM leads delivery enablement (5.3).' },
      { id: 'F21Q22', topic: 'IN', q: 'Geoff Watts\' commandment \'Make yourself redundant\' measures a Scrum Master\'s success primarily by what?', options: ['How many impediments they personally remove each Sprint', 'How closely they direct the Developers\' daily tasks', 'The team becoming more autonomous, capable and empowered', 'Whether they replace the Project Manager'], correct: 'The team becoming more autonomous, capable and empowered', explain: 'True leadership is shown when the team grows more autonomous through coaching, not through the SM directing work (5.3.6).' },
      { id: 'F21Q23', topic: 'IN', q: 'A Workshop Facilitator is an example of which Advisor role?', options: ['Business Advisor', 'Solution Advisor', 'Process Advisor', 'Value Advisor'], correct: 'Process Advisor', explain: 'Process Advisors (e.g. Agile Coach, Workshop Facilitator) guide how practices are tailored and run (5.4).' },
      { id: 'F21Q24', topic: 'CC', q: 'On the Aligned Autonomy Matrix, which combination describes an innovative, collaborative culture?', options: ['High alignment and low autonomy', 'Low alignment and low autonomy', 'High alignment and high autonomy', 'Low alignment and high autonomy'], correct: 'High alignment and high autonomy', explain: 'High alignment + high autonomy is the innovative / collaborative culture AgilePM seeks (6.3).' },
      { id: 'F21Q25', topic: 'CC', q: 'Projects often stall because information does not flow. Which of the following are recognised communication failure modes?\n1. Not using a shared language\n2. Lack of access to the right people at the right time\n3. Over-reliance on written communication instead of face-to-face or visual methods\n4. Agreeing communication methods, style and frequency in advance', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Failing to agree methods causes confusion; agreeing them in advance is good practice, not a failure (6.1.2).' },
      { id: 'F21Q26', topic: 'CC', q: 'Identify the missing words. On the Power/Interest Grid, a stakeholder with high power and low interest should be [ ? ].', options: ['closely engaged', 'monitored with minimum effort', 'kept satisfied', 'kept informed'], correct: 'kept satisfied', explain: 'High power / low interest → keep satisfied; high/high → closely engage (6.3).' },
      { id: 'F21Q27', topic: 'CC', q: 'Consider the statements about email as a communication choice.\n1. Email is the most efficient method of conveying information within a team\n2. Email is best used to confirm previous discussions rather than as the primary communication method', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Face-to-face is the most efficient method; email confirms discussions rather than replacing them (6.3).' },
      { id: 'F21Q28', topic: 'PR', q: 'Which of the following correctly describe increment types in AgilePM?\n1. A Product Increment is the combination of products plus training, communications and business change\n2. A Product Increment is a stepwise refinement of a product that meets the Definition of Done\n3. A Solution Increment is a stepwise refinement of the overall solution, which may combine multiple products and other deliverables\n4. When a Solution Increment is deployed it becomes or adds to the Deployed Solution', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Statement 1 describes a Solution Increment, not a Product Increment (7.1).' },
      { id: 'F21Q29', topic: 'PR', q: 'Why does AgilePM keep the first Foundations pass high-level and relatively short, even on a large project?', options: ['Developers must not be involved until Deployment', 'The Business Case is forbidden until Realisation', 'Fine details are left for the Delivery Phase so Foundations is not delayed', 'Sprint length must equal Foundations duration'], correct: 'Fine details are left for the Delivery Phase so Foundations is not delayed', explain: 'Foundations lasts only a few weeks even for large projects because fine detail waits for Delivery (7.4).' },
      { id: 'F21Q30', topic: 'PR', q: 'Identify the missing word. Each Sprint should aim to deliver a [ ? ] slice that contains all required elements so the increment can be used.', options: ['vertical', 'horizontal', 'technical-only', 'documentation'], correct: 'vertical', explain: 'A vertical / Done slice includes UI, logic and data so it is usable; a horizontal layer delays value (7.5).' },
      { id: 'F21Q31', topic: 'PR', q: 'Consider the statements about the Realisation Phase.\n1. Its purpose is to make sure the solution provides the predicted value after deployment\n2. Where deployment is ongoing, realisation should also be ongoing and can continue beyond the end of the project', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Realisation ensures predicted value is achieved and continues with ongoing deployment, including after the project (7.2, 7.7).' },
      { id: 'F21Q32', topic: 'PR', q: 'What is the main goal of the Pre-Project Phase regarding investment?', options: ['To get approval for a small initial investment to explore whether the project is worth pursuing', 'To evaluate full technical feasibility in detail', 'To baseline every Project Artifact', 'To select the Sprint length for all teams'], correct: 'To get approval for a small initial investment to explore whether the project is worth pursuing', explain: 'Pre-Project is not a feasibility evaluation; it seeks a small investment to explore further (7.3).' },
      { id: 'F21Q33', topic: 'ES', q: 'In the INVEST model, what does Negotiable mean for a User Story?', options: ['It remains flexible and open to discussion', 'It is locked once written on a card', 'It cannot be split', 'It must be estimated in hours'], correct: 'It remains flexible and open to discussion', explain: 'Negotiable means the story stays flexible and open to discussion (8.2.3.4).' },
      { id: 'F21Q34', topic: 'ES', q: 'Which of the following are true about MoSCoW effort guidance?\n1. Must Have effort should be no more than about 60% of total effort\n2. Could Haves typically provide the main pool of contingency at around 20% of effort\n3. Won\'t Haves this time are included in the total effort calculation\n4. In a high-risk project it may be wise to reduce the Must Have proportion further', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Won\'t Haves are out of scope for the timeframe and excluded from the effort total (9.2, 9.5).' },
      { id: 'F21Q35', topic: 'ES', q: 'Identify the missing words. AgilePM recommends that the worst-case benefits in the Business Case are based on [ ? ].', options: ['just the Must Haves', 'Musts plus Shoulds', 'the full scope including Coulds', 'Won\'t Haves only'], correct: 'just the Must Haves', explain: 'Worst case = Musts; expected = Musts+Shoulds; best = Musts+Shoulds+Coulds. Costs cover full scope (9.7).' },
      { id: 'F21Q36', topic: 'ES', q: 'Consider the statements about Velocity.\n1. Velocity is a measure of outcomes rather than output\n2. Velocity from one Delivery Team should be used as a benchmark to judge another team', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Neither 1 nor 2 is true', explain: 'Velocity measures output, not outcomes, and is unique to each team — it must not be used to compare teams (8.3).' },
      { id: 'F21Q37', topic: 'ES', q: 'During Feasibility, which estimating style is commonly used for a small number of Epic User Stories?', options: ['Estimating by analogy, such as T-shirt sizes expressed as time ranges', 'Planning Poker in story points only', 'Hour-level decomposition of every task', 'A single-figure commitment chosen by the estimator'], correct: 'Estimating by analogy, such as T-shirt sizes expressed as time ranges', explain: 'Feasibility uses analogy (e.g. T-shirt sizes as week/month ranges), not precise story-point or hour decomposition (8.3.5).' },
      { id: 'F21Q38', topic: 'ES', q: 'If an unexpected problem consumes contingency early in a timebox, which class of requirement is typically dropped first?', options: ['Could Haves', 'Must Haves', 'Should Haves', 'Won\'t Haves'], correct: 'Could Haves', explain: 'Could Haves are the main contingency buffer and are dropped first to protect Musts and Shoulds (9.2.3).' },
      { id: 'F21Q39', topic: 'PC', q: 'Which of the following is one of AgilePM\'s three planning concepts rather than a tracking and control concept?', options: ['Plan and re-plan using the most up-to-date estimates', 'Outcome-based measurement', 'Transparency of process and progress', 'Management by exception'], correct: 'Plan and re-plan using the most up-to-date estimates', explain: 'The three planning concepts are outcome-based planning, planning to sensible horizons, and plan/re-plan on latest estimates. The other three are control concepts (10.1).' },
      { id: 'F21Q40', topic: 'PC', q: 'Which of the following are typical multi-team events or activities in an AgilePM project context?\n1. Project Sprint Planning\n2. Using the Daily Scrum to agree Developer vacation cover for the quarter\n3. Cross-Team Refinement\n4. Project Sprint Review', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The Daily Scrum inspects progress toward the Sprint Goal; quarterly vacation cover is medium-term planning, not a Daily Scrum topic (10.2, 10.5).' },
      { id: 'F21Q41', topic: 'PC', q: 'Consider the statements about Management by Exception.\n1. Every minor slip against a task estimate must be escalated immediately to the Business Sponsor\n2. An exception arises if the Delivery Team determines that the Sprint Goal is at risk, for example if agreed Must Haves will not be delivered', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Only major deviations (Sprint Goal / Must Haves at risk) are exceptions; minor slips stay with the Delivery Team (10.4.2).' },
      { id: 'F21Q42', topic: 'PC', q: 'Identify the missing words. Project Sprint Planning mirrors the first [ ? ] of standard Sprint Planning.', options: ['two topics (why it is valuable and what can be Done)', 'three topics, including how the work will get done', 'topic only (why the Sprint is valuable)', 'four Scrum events'], correct: 'two topics (why it is valuable and what can be Done)', explain: 'Project Sprint Planning covers Why and What; How is Delivery Team Sprint Planning, which produces each Sprint Backlog (10.2.3.4).' },
      { id: 'F21Q43', topic: 'PC', q: 'A Project Manager proposes using each Daily Scrum to collect Developer holiday requests for the next quarter. Why is this an inappropriate application of planning to sensible horizons?', options: ['Holiday requests must instead be collected only by the Business Sponsor', 'The Daily Scrum is a short inspect-and-adapt of progress toward the Sprint Goal, not a forum for medium-term absence planning', 'Vacation planning is forbidden in AgilePM', 'Only the Scrum Master may discuss absences, and only in the Retrospective'], correct: 'The Daily Scrum is a short inspect-and-adapt of progress toward the Sprint Goal, not a forum for medium-term absence planning', explain: 'Specialist/absence availability is agreed at a sensible horizon (e.g. Foundations or Sprint Planning), not inside the 15-minute Daily Scrum (10.2.2, 3.5).' },
      { id: 'F21Q44', topic: 'RK', q: 'Which of the following are true about risk in AgilePM?\n1. Risk often arises as a direct consequence of VUCA\n2. Risk management is fully integrated into day-to-day execution of the approach\n3. The PAQ is used to identify approach-based risk so that mitigating action can be taken\n4. A separate, formal risk-management process is required on every AgilePM project regardless of context', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'A separate formal process is usually unnecessary except perhaps in highly regulated or safety-related contexts (11.1–11.2).' },
      { id: 'F21Q45', topic: 'RK', q: 'Why does AgilePM recommend completing the PAQ during Feasibility rather than waiting until Delivery?', options: ['Because Feasibility is the only phase that produces a Delivery Plan', 'Because even at that early stage it highlights risks so preventive actions can be taken', 'Because the PAQ replaces the Business Case', 'Because Scrum Teams cannot form until after Foundations'], correct: 'Because even at that early stage it highlights risks so preventive actions can be taken', explain: 'The PAQ is usually first used in Feasibility so risks are visible early enough to prevent (11.2.1).' },
      { id: 'F21Q46', topic: 'RK', q: 'Team members disagree with several PAQ statements. What is the appropriate next step?', options: ['Ignore the scores if the Business Sponsor still wants to start Delivery immediately', 'Treat each disagreement as a risk and tailor the AgilePM approach with mitigating actions, typically during Foundations', 'Treat disagreement as proof that AgilePM cannot be used and stop all tailoring', 'Re-run the PAQ until everyone strongly agrees, without changing the approach'], correct: 'Treat each disagreement as a risk and tailor the AgilePM approach with mitigating actions, typically during Foundations', explain: 'Any statement not considered true indicates risk; resolve by tailoring and mitigation, especially in Foundations (11.2.1).' },
      { id: 'F21Q47', topic: 'GV', q: 'Identify the missing words. If a Business Sponsor insists on a single-figure estimate, that figure should be chosen by [ ? ] from the range provided.', options: ['the estimator who produced the range', 'the Business Sponsor', 'the Scrum Master', 'the Developers alone'], correct: 'the Business Sponsor', explain: 'The Sponsor, not the estimator, chooses any single figure after discussing understanding, assumptions and risk (12.3.1).' },
      { id: 'F21Q48', topic: 'GV', q: 'Which of the following support financial governance in AgilePM?\n1. Velocity charts used to rank Delivery Teams\n2. The Feasibility Assessment giving an early view of whether the project is likely to make business sense\n3. The Business Case explaining value and cost\n4. Benefits Assessment measuring observed benefits after live use', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Financial artifacts include Feasibility Assessment, Business Case, Foundations Summary, Project Review Report and Benefits Assessment — not velocity league tables (12.3.2).' },
      { id: 'F21Q49', topic: 'GV', q: 'In the project context, what does governance mean?', options: ['Learning through experience only, with no structures allowed', 'The set of processes, structures and controls that ensure a project is well managed and meeting its objective', 'A requirement to reverse the Agile Manifesto values', 'The Scrum Master\'s personal authority over the budget'], correct: 'The set of processes, structures and controls that ensure a project is well managed and meeting its objective', explain: 'Governance and empiricism are not opposites if governance is designed around its purpose (12.1).' },
      { id: 'F21Q50', topic: 'GV', q: 'Which emphasis would indicate that governance has been applied in a way that undermines agility?', options: ['Using plans as flexible guides', 'Sticking rigidly to the original plan even when the situation has changed', 'Creating documentation only where it adds value', 'Focusing on skilled people working together'], correct: 'Sticking rigidly to the original plan even when the situation has changed', explain: 'That is the Manifesto in reverse (following a plan over responding to change) and blocks empiricism (12.1.1).' },
    ],
  },
  {
    id: 'final22',
    title: 'Final Paper 22',
    questions: [
      { id: 'F22Q1', topic: 'KC', q: 'Which of the following correctly describe the last responsible moment?\n1. It is the point when information is actually needed to take the next step\n2. Detailed analysis, design and planning are completed at that moment, not far in advance\n3. It requires every detailed decision to be made in Pre-Project\n4. Later decisions are often better because teams have learned and tested assumptions', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Detail is deferred until it is needed; Pre-Project is far too early for detailed decisions (2.4.2).' },
      { id: 'F22Q2', topic: 'KC', q: 'Identify the missing words. Complexity in VUCA means many interconnected parts make situations hard to manage because the connection between [ ? ] is no longer clear.', options: ['budget and timescale', 'Sponsor and Visionary', 'Must and Should', 'cause and effect'], correct: 'cause and effect', explain: 'Complexity is when cause and effect are no longer clear because of interconnected parts (2.1.2).' },
      { id: 'F22Q3', topic: 'KC', q: 'How does AgilePM define a customer?', options: ['Only the person who signs the commercial contract', 'Only end users of a software product', 'Only the Business Sponsor', 'Anyone — individual or organisation — who will benefit from the project\'s work'], correct: 'Anyone — individual or organisation — who will benefit from the project\'s work', explain: 'Customer includes buyers, users and others affected by what the project delivers or changes (2.1.3).' },
      { id: 'F22Q4', topic: 'KC', q: 'Consider the statements about the Manifesto\'s final sentence.\n1. Items on the right have no value and should be eliminated\n2. Items on the right are still useful when they add real value and include just enough detail', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The left is valued more; the right is not worthless (2.1.3.5).' },
      { id: 'F22Q5', topic: 'KC', q: 'Which pairing correctly contrasts Product Lifecycle Management with project management?', options: ['PLM is only about fixing time and cost; project management is only about coding', 'They are identical and interchangeable terms in AgilePM', 'Project management replaces PLM once Feasibility starts', 'PLM looks across ideation, servicing and retirement; project management delivers time-bound outcomes within parameters'], correct: 'PLM looks across ideation, servicing and retirement; project management delivers time-bound outcomes within parameters', explain: 'PLM is the long-term product view; projects provide focus, coordination and investment control (2.2–2.3).' },
      { id: 'F22Q6', topic: 'SC', q: 'In the Scrum nutshell, who orders the work for a complex problem into a Product Backlog?', options: ['The Project Manager', 'The Business Sponsor', 'The Scrum Master', 'The Product Owner'], correct: 'The Product Owner', explain: 'Step 1 of the nutshell: the Product Owner orders work into the Product Backlog (3.1).' },
      { id: 'F22Q7', topic: 'SC', q: 'Which of the following are Scrum Values?\n1. Commitment\n2. Focus\n3. Consensus\n4. Openness', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The five values are Commitment, Focus, Openness, Respect and Courage — not Consensus (3.3).' },
      { id: 'F22Q8', topic: 'SC', q: 'Identify the missing words. The Sprint is described as the [ ? ] of Scrum, where ideas are turned into value.', options: ['contract', 'governance gate', 'portfolio', 'heartbeat'], correct: 'heartbeat', explain: 'The Sprint is the heartbeat of Scrum (3.5).' },
      { id: 'F22Q9', topic: 'SC', q: 'Consider the statements about the Sprint Review.\n1. It should be limited to a presentation by Developers to management\n2. It is a working session in which the Scrum Team and stakeholders inspect the outcome and collaborate on what to do next', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The Review must not be reduced to a presentation (3.5).' },
      { id: 'F22Q10', topic: 'SC', q: 'What is the typical maximum size of a Scrum Team, and why?', options: ['15 or more — so specialists never share skills', 'Exactly 7, including the Project Manager as a fourth role', 'Unlimited, provided a steering committee approves', '10 or fewer — small enough to stay nimble, large enough to complete significant work'], correct: '10 or fewer — small enough to stay nimble, large enough to complete significant work', explain: 'Scrum Teams are typically 10 or fewer people (3.4).' },
      { id: 'F22Q11', topic: 'SC', q: 'Which of the following are ways the Scrum Master serves the organisation?\n1. Leading, training and coaching the organisation in Scrum adoption\n2. Planning and advising Scrum implementations\n3. Directing Developers\' technical design choices each day\n4. Helping employees and stakeholders enact empirical approaches', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The SM does not direct technical design; Developers decide how the work is done (3.4).' },
      { id: 'F22Q12', topic: 'AF', q: 'Consider the statements about the four project variables.\n1. In a traditional sequential approach, features are typically fixed while time and cost vary\n2. In AgilePM, time, cost and quality are fixed and features are varied, protected by the Definition of Done', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The two triangles reverse which variable is flexed (4.2).' },
      { id: 'F22Q13', topic: 'AF', q: 'Under Focus on the Business Need, what is true of the Project Manager and the Business Case?', options: ['The Project Manager writes and owns the Business Case instead of the Value Ownership roles', 'The Business Case is optional once Sprints have started', 'The Project Manager may ignore the Business Case if the Product Goal is clear', 'The Project Manager does not create the Business Case but must ensure it receives appropriate attention throughout'], correct: 'The Project Manager does not create the Business Case but must ensure it receives appropriate attention throughout', explain: 'Value Ownership owns the Business Case; the PM ensures it stays in view (4.3).' },
      { id: 'F22Q14', topic: 'AF', q: 'Identify the missing words. Principle 3 (Collaborate) requires the Project Manager to help build a [ ? ] culture focused on the success of the entire Project Organisation.', options: ['command-and-control', 'contract-first', 'documentation-led', 'one-team'], correct: 'one-team', explain: 'Collaborate builds a one-team culture across the Project Organisation (4.3).' },
      { id: 'F22Q15', topic: 'AF', q: 'Which of the following are AgilePM Practices that enable the principles?\n1. Iterative Development\n2. Timeboxing\n3. MoSCoW Prioritisation\n4. Fixed-scope contract negotiation as the primary control', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The five practices are Iterative Development, Timeboxing, MoSCoW, Modelling and Facilitated Workshops (4.3).' },
      { id: 'F22Q16', topic: 'AF', q: 'Under Demonstrate Control, how should progress be measured?', options: ['By completed activities and status reports alone', 'By the number of documents signed in Foundations', 'By comparing team velocities in a league table', 'Based on product delivery and working solutions rather than completed tasks'], correct: 'Based on product delivery and working solutions rather than completed tasks', explain: 'Progress is working solutions, not task completion; reports can be outdated (4.3).' },
      { id: 'F22Q17', topic: 'IN', q: 'Identify the missing words. One Agile Leadership principle states that leadership is a [ ? ], not a position.', options: ['budget line', 'RACI code', 'Sprint event', 'mindset'], correct: 'mindset', explain: 'Leadership is a mindset, not a position — one of the nine principles (5.1).' },
      { id: 'F22Q18', topic: 'IN', q: 'Which of the following are Business Sponsor accountabilities?\n1. Owning the Business Case and holding the project budget\n2. Acting as final authority on critical project decisions\n3. Estimating story points during Planning Poker\n4. Resolving escalated issues', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Developers estimate; the Sponsor does not play Planning Poker (5.3).' },
      { id: 'F22Q19', topic: 'IN', q: 'What is the Solution Architect\'s balancing role relative to the Business Visionary?', options: ['To replace the Visionary on all value decisions', 'To hold the project budget instead of the Sponsor', 'To cancel Sprints when the Sprint Goal is obsolete', 'To balance the Visionary\'s ambitions so the solution remains realistic and feasible'], correct: 'To balance the Visionary\'s ambitions so the solution remains realistic and feasible', explain: 'The SA keeps the solution feasible while the BV drives ambition and value (5.3).' },
      { id: 'F22Q20', topic: 'IN', q: 'Consider the statements about roles and people.\n1. Roles do not necessarily equate to people; one person may fulfil more than one role\n2. A single role may be shared between multiple people if necessary', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both flexibilities are explicit in AgilePM, provided accountabilities stay clear (5.3).' },
      { id: 'F22Q21', topic: 'IN', q: 'Which of the following correctly reflect Geoff Watts\' commandments for a Scrum Master?\n1. First ask the team\n2. Make yourself redundant\n3. Direct the Sprint Backlog each morning\n4. Default to the team\'s knowledge and context before offering your own answer', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The SM does not direct the Sprint Backlog; Developers own that plan (5.3.6).' },
      { id: 'F22Q22', topic: 'IN', q: 'Why must the Product Owner be one person rather than a committee?', options: ['Because committees are forbidden in AgilePM', 'Because only one person may speak to the Business Sponsor', 'Because the Scrum Master cannot coach more than one Product Owner', 'Because they represent many stakeholders in the Product Backlog and the organisation must respect their decisions'], correct: 'Because they represent many stakeholders in the Product Backlog and the organisation must respect their decisions', explain: 'One PO represents many needs; a committee Product Owner is not Scrum (3.4, 5.3.5).' },
      { id: 'F22Q23', topic: 'IN', q: 'Which four factors influence how external stakeholders interact with the project?', options: ['Budget, Velocity, MoSCoW and DoD', 'Card, Conversation, Confirmation and Context', 'Purpose, Timing, Authority and Constraints', 'Transparency, Inspection, Adaptation and Documentation'], correct: 'Purpose, Timing, Authority and Constraints', explain: 'Those four factors shape external-stakeholder interaction (5.2).' },
      { id: 'F22Q24', topic: 'CC', q: 'Which of the following are stated benefits of collaboration?\n1. Improved problem-solving\n2. Improved learning\n3. Reduced autonomy as a desired outcome\n4. Increased productivity', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Benefits are problem-solving, learning, productivity and cross-functional learning — not reduced autonomy (6.2).' },
      { id: 'F22Q25', topic: 'CC', q: 'Consider the statements about Jim Highsmith\'s observation.\n1. Documentation is not understanding\n2. Process is not discipline, and formality is not skill', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The full quote is documentation ≠ understanding, process ≠ discipline, formality ≠ skill (6.4).' },
      { id: 'F22Q26', topic: 'CC', q: 'What does Active Listening require a listener to do before responding?', options: ['Interrupt quickly with a solution', 'Draft an email summary instead of attending', 'Pay attention, show they are listening, defer judgement until the speaker has finished, then respond appropriately', 'Record the conversation for the Project Review Report only'], correct: 'Pay attention, show they are listening, defer judgement until the speaker has finished, then respond appropriately', explain: 'Active listening defers judgement until the speaker has finished (6.3).' },
      { id: 'F22Q27', topic: 'CC', q: 'Identify the missing words. Community collaboration promotes a sense of unity among all teams delivering value and relies on applying the [ ? ].', options: ['Cone of Uncertainty', 'four Scrum events only', 'nine Principles of Agile Leadership', 'PAQ Statement 17 alone'], correct: 'nine Principles of Agile Leadership', explain: 'Community collaboration depends on the nine leadership principles and collaboration agreements (6.2).' },
      { id: 'F22Q28', topic: 'PR', q: 'Consider the statements about lifecycle phases.\n1. Every project should go through the same lifecycle phases, though effort and formality vary\n2. Feasibility is optional if the Sponsor already likes the idea', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Phases are the same; intensity varies. Feasibility still checks desirability, feasibility and viability (7.2).' },
      { id: 'F22Q29', topic: 'PR', q: 'What three questions does the Feasibility Phase examine?', options: ['Sprint Goal, Sprint Backlog and Daily Scrum attendance', 'Only cost, to two decimal places', 'Solution feasibility, stakeholder desirability and viability, and people\'s capability to work in an agile way', 'Only whether the Product Owner has been hired'], correct: 'Solution feasibility, stakeholder desirability and viability, and people\'s capability to work in an agile way', explain: 'Those three lenses are the Feasibility examination (7.3).' },
      { id: 'F22Q30', topic: 'PR', q: 'Which of the following are timebox types AgilePM considers?\n1. Overall Project Timebox\n2. Project Increment Timebox\n3. Delivery Timeboxes (Sprints)\n4. Unlimited open-ended discovery with no end date', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'AgilePM uses nested project, increment and delivery timeboxes — not unbounded discovery (7.1).' },
      { id: 'F22Q31', topic: 'PR', q: 'Identify the missing words. A Project Increment Timebox is bound at each end by a revisit of [ ? ] and a Project Increment Review.', options: ['the Daily Scrum', 'Pre-Project only', 'the Foundations Phase', 'the PAQ Statement 1 training course'], correct: 'the Foundations Phase', explain: 'Project Increments are bounded by Foundations at the start and an Increment Review at the end (7.1).' },
      { id: 'F22Q32', topic: 'PR', q: 'At what point does AgilePM treat a Deployment Phase as finished for the increment being released?', options: ['When the first User Story is written', 'When Foundations artifacts are outlined', 'When the solution (or the planned part of it) is in live operational use', 'When the Sprint Goal is drafted'], correct: 'When the solution (or the planned part of it) is in live operational use', explain: 'Deployment completes when the increment is in operational use; it may be ongoing with Delivery (7.6).' },
      { id: 'F22Q33', topic: 'ES', q: 'Which of the following are part of the Three Cs of a User Story?\n1. Card\n2. Conversation\n3. Contract\n4. Confirmation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Three Cs are Card, Conversation and Confirmation. Contract is not one; some add Context as a fourth (8.2.3).' },
      { id: 'F22Q34', topic: 'ES', q: 'Identify the missing word. For a User Story to be Independent in INVEST, it should not be [ ? ] on other stories, so replanning remains possible.', options: ['valuable', 'testable', 'dependent', 'estimable'], correct: 'dependent', explain: 'Independent means not dependent on other stories, enabling replanning (8.2.3.4).' },
      { id: 'F22Q35', topic: 'ES', q: 'Which technique writes Acceptance Criteria as Given / When / Then scenarios?', options: ['MoSCoW', 'T-shirt sizing', 'Behaviour-Driven Development (BDD)', 'Management by Exception'], correct: 'Behaviour-Driven Development (BDD)', explain: 'Dan North\'s BDD Given/When/Then format is used for scenario-style Acceptance Criteria (8.2.3.4).' },
      { id: 'F22Q36', topic: 'ES', q: 'Consider the statements about Must Have dependencies.\n1. A Must Have may depend on a Could Have if the Could Have is interesting to Developers\n2. A Must Have cannot depend on anything other than a Must Have, because Shoulds and Coulds might not be delivered', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Musts may depend only on other Musts (9.8).' },
      { id: 'F22Q37', topic: 'ES', q: 'Which of the following are true about estimating styles in AgilePM?\n1. Estimating by analogy compares work to similar past items\n2. Estimating by decomposition breaks work into smaller parts\n3. Using both styles together can cross-check estimates\n4. The Project Manager must produce the Developers\' estimates to protect the budget', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The people doing the work estimate it; the PM must not take over estimating (8.3).' },
      { id: 'F22Q38', topic: 'ES', q: 'What should benefit estimates be based on, according to AgilePM\'s MoSCoW/Business Case guidance?', options: ['Won\'t Haves only', 'Could Haves only', 'Delivering Must Have and Should Have requirements', 'Whatever the supplier puts in the contract appendix'], correct: 'Delivering Must Have and Should Have requirements', explain: 'Benefits = Musts+Shoulds (expected case); costs cover the full in-scope set (9.7).' },
      { id: 'F22Q39', topic: 'PC', q: 'Consider the statements about planning versus tracking concepts.\n1. Outcome-based planning is a planning concept focused on delivering real business value, including Realisation\n2. Outcome-based measurement is a tracking concept that tracks progress by delivered value, not just tasks completed', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Similar names, different lists: planning vs the four control concepts (10.1–10.2).' },
      { id: 'F22Q40', topic: 'PC', q: 'Identify the missing role. When an exception affects the broader project, it must also be escalated to the [ ? ].', options: ['Project Manager', 'Business Advisor only', 'external regulator', 'Workshop Facilitator'], correct: 'Project Manager', explain: 'Broader delivery exceptions escalate to the PM, who collaborates with the PO and, if appropriate, the BV (10.4.2).' },
      { id: 'F22Q41', topic: 'PC', q: 'What should also be remembered about the Daily Scrum and a Scrum of Scrums?', options: ['Teams are expected to collaborate as needed; those events are not the only time people can interact', 'They are the only permitted times people may interact', 'A Scrum of Scrums replaces all team Daily Scrums', 'Only the Business Sponsor may attend either event'], correct: 'Teams are expected to collaborate as needed; those events are not the only time people can interact', explain: 'SoS and Daily Scrum are useful, not exclusive, collaboration windows (10.2.3.6).' },
      { id: 'F22Q42', topic: 'PC', q: 'Which of the following correctly describe Project Sprint Planning?\n1. The Agile Project Manager facilitates\n2. The Product Owner and representatives from relevant Delivery Teams are present\n3. It replaces Delivery Team Sprint Planning, so teams never create their own Sprint Backlogs\n4. Other Project Roles and Advisors may attend to guide and support', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Team Sprint Planning still follows (Topic 3 / How) and produces each Sprint Backlog (10.2.3.4).' },
      { id: 'F22Q43', topic: 'PC', q: 'What is a recommended duration and frequency for Cross-Team Refinement?', options: ['1–3 hours, at least once every Sprint', '15 minutes every working day, replacing Daily Scrums', 'One full week at the end of the project only', 'Eight hours every day of the Sprint'], correct: '1–3 hours, at least once every Sprint', explain: 'CTR is typically 1–3 hours and at least once per Sprint; teams experiment (10.2.3.6).' },
      { id: 'F22Q44', topic: 'RK', q: 'Identify the missing words. AgilePM treats risk as arising as a direct consequence of [ ? ], so its management is integrated into day-to-day execution.', options: ['VUCA', 'the Daily Scrum agenda', 'the Sprint Retrospective', 'Parkinson\'s Law alone'], correct: 'VUCA', explain: 'Risk is a VUCA consequence; management is built into the approach, not a bolt-on on every project (11.1).' },
      { id: 'F22Q45', topic: 'RK', q: 'Consider the statements about PAQ timing.\n1. The PAQ should be reviewed again at the end of Foundations and every time Foundations is revisited\n2. Once completed in Feasibility, the PAQ must never be looked at again', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Review at end of Foundations (and each revisit) checks that tailoring remains relevant (11.2.1).' },
      { id: 'F22Q46', topic: 'RK', q: 'If all project team members agree or strongly agree with every PAQ statement, what does that indicate?', options: ['AgilePM with Scrum should work effectively, though this situation is rare in organisations new to agility', 'The project must be stopped because unanimous agreement is a risk', 'The PAQ has failed and must be rewritten by the auditor', 'MoSCoW may no longer be used'], correct: 'AgilePM with Scrum should work effectively, though this situation is rare in organisations new to agility', explain: 'Full agreement is the ideal and uncommon; the PAQ exists to find the usual gaps (11.2.1).' },
      { id: 'F22Q47', topic: 'GV', q: 'Which of the following are true about the Cone (Core) of Uncertainty?\n1. Early estimates are inherently vague\n2. Estimate ranges should narrow as the lifecycle progresses\n3. Delivery-phase estimates are still as wide as Pre-Project concept estimates\n4. AgilePM recommends ranges rather than single figures', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Understanding improves through Feasibility, Foundations and Delivery, so ranges tighten (12.3.1).' },
      { id: 'F22Q48', topic: 'GV', q: 'Who is Responsible and who is Accountable for the Terms of Reference?', options: ['Responsible: Business Visionary; Accountable: Business Sponsor', 'Responsible: Project Manager; Accountable: Product Owner', 'Responsible: Solution Architect; Accountable: Scrum Master', 'Responsible: Developers; Accountable: Product Owner'], correct: 'Responsible: Business Visionary; Accountable: Business Sponsor', explain: 'ToR R = BV, A = BS (Appendix A).' },
      { id: 'F22Q49', topic: 'GV', q: 'By default, how does AgilePM control time and cost for financial governance?', options: ['Through MoSCoW prioritisation and timeboxing', 'By extending the Project Timebox whenever Must Haves slip', 'By adding percentage contingency to every estimate in secret', 'By freezing the Product Backlog after Pre-Project'], correct: 'Through MoSCoW prioritisation and timeboxing', explain: 'Default controls are MoSCoW and timeboxing (12.3.1).' },
      { id: 'F22Q50', topic: 'GV', q: 'Identify the missing word. Agile governance should be designed around the [ ? ] of the controls, not around copying traditional procedures.', options: ['purpose', 'templates', 'page count', 'steering-committee minutes'], correct: 'purpose', explain: 'Design processes that support the purpose of governance without limiting agility (12.1).' },
    ],
  },
  {
    id: 'final23',
    title: 'Final Paper 23',
    questions: [
      { id: 'F23Q1', topic: 'KC', q: 'Which characteristic of people and systems best helps them cope with VUCA?', options: ['Strict procedure-following with no discretion', 'Waiting for a complete specification before any action', 'Isolating specialists so they never share context', 'Flexible, adaptable, thoughtful, collaborative and good at solving problems'], correct: 'Flexible, adaptable, thoughtful, collaborative and good at solving problems', explain: 'Those human characteristics are what AgilePM says cope with VUCA (2.1.2).' },
      { id: 'F23Q2', topic: 'KC', q: 'Which of the following correctly state Manifesto principles in the form AgilePM uses for projects?\n1. Welcome changing requirements, even late\n2. Working solutions are the primary measure of progress\n3. Fix all requirements at the outset and resist change\n4. The best outcomes emerge from self-organising teams', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Welcoming change and self-organisation are principles; fixing requirements at the outset is not (2.1.4).' },
      { id: 'F23Q3', topic: 'KC', q: 'Identify the missing words. The Agile Business Consortium enhanced the Manifesto for the project context by broadening \'software\' to [ ? ].', options: ['hardware', 'contracts', 'portfolios', 'solutions'], correct: 'solutions', explain: 'ABC replaced software with solutions so the values apply beyond software (2.1.3).' },
      { id: 'F23Q4', topic: 'KC', q: 'Consider the statements about empowerment.\n1. Empowerment requires people to be capable, willing and informed\n2. Boundaries of empowerment describe how much freedom someone has to act without extra approval', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both the three conditions and the idea of empowerment boundaries are AgilePM teaching (2.1.3).' },
      { id: 'F23Q5', topic: 'KC', q: 'In a VUCA setting, why does AgilePM treat long-horizon, highly detailed plans as poor value?', options: ['Because AgilePM forbids any planning beyond the next Daily Scrum', 'Because the Business Sponsor may not read them', 'Because Scrum has no events in which plans can be inspected', 'Because change happens quickly and detailed plans become outdated very quickly'], correct: 'Because change happens quickly and detailed plans become outdated very quickly', explain: 'Prefer high-level, light-touch, guiding plans with short- to medium-term goals adjusted as needed (2.1.3).' },
      { id: 'F23Q6', topic: 'SC', q: 'Identify the missing number. Sprint Planning is timeboxed to a maximum of [ ? ] hours for a one-month Sprint.', options: ['15 minutes', '3', '4', '8'], correct: '8', explain: 'Planning max 8h; Review 4h; Retro 3h; Daily Scrum 15 minutes (3.5).' },
      { id: 'F23Q7', topic: 'SC', q: 'What are Developers accountable for creating as the plan for the Sprint?', options: ['The Business Case', 'The Terms of Reference', 'The Management Approach Definition', 'The Sprint Backlog'], correct: 'The Sprint Backlog', explain: 'Developers create the Sprint Backlog (why/what/how) and adapt it daily (3.4).' },
      { id: 'F23Q8', topic: 'SC', q: 'Which of the following are Scrum events that occur within the Sprint?\n1. Sprint Planning\n2. Daily Scrum\n3. Feasibility Assessment workshop as a required Scrum event\n4. Sprint Retrospective', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The five events are Sprint, Planning, Daily Scrum, Review and Retro. Feasibility Assessment is an AgilePM artifact, not a Scrum event (3.5).' },
      { id: 'F23Q9', topic: 'SC', q: 'Consider the statements about quality during the Sprint.\n1. No changes are allowed that would endanger the Sprint Goal\n2. Quality does not decrease during the Sprint', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both are Sprint rules; scope may be clarified with the PO as more is learned (3.5).' },
      { id: 'F23Q10', topic: 'SC', q: 'What commitment is attached to the Increment?', options: ['The Product Goal', 'The Sprint Goal', 'The Solution Goal', 'The Definition of Done'], correct: 'The Definition of Done', explain: 'Increment → Definition of Done (3.6).' },
      { id: 'F23Q11', topic: 'SC', q: 'Which of the following correctly describe Product Backlog refinement?\n1. It breaks items into smaller, more precise items\n2. It is an ongoing activity that adds details such as description, order and size\n3. It is a one-off workshop that freezes the backlog at the end of Pre-Project\n4. It helps items become ready for Sprint Planning', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Refinement is ongoing; the backlog remains emergent (3.6).' },
      { id: 'F23Q12', topic: 'AF', q: 'Which of the four foundational elements of the AgilePM Framework concerns clearly defined roles and responsibilities?', options: ['Process', 'Project Artifacts', 'Practices', 'People'], correct: 'People', explain: 'People = clearly defined roles and responsibilities (4.1).' },
      { id: 'F23Q13', topic: 'AF', q: 'Consider the statements about Deliver on Time.\n1. A delayed Solution Increment can lose its value, especially if it depends on a market opportunity or legal deadline\n2. Artificial deadlines used only as a measure of success or control can harm the project', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'On-time delivery is critical for real business need; fake deadlines are harmful (4.3).' },
      { id: 'F23Q14', topic: 'AF', q: 'Which of the following must high-level plans, designs and standards define under Demonstrate Control?\n1. What needs to be done\n2. How it will be achieved\n3. The name of every task owner for the whole project on day one\n4. When it will be delivered', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Demonstrate Control requires what, how and when — not a frozen named-task plan for the entire project (4.3).' },
      { id: 'F23Q15', topic: 'AF', q: 'Identify the missing words. A partially completed feature has [ ? ] business value than a feature not started.', options: ['more', 'the same', 'infinite', 'less'], correct: 'less', explain: 'Incomplete work adds complication without adding value, so it is worth less than work not started (4.3).' },
      { id: 'F23Q16', topic: 'AF', q: 'What extra support does the AgilePM project context give a Product Owner who is using Scrum?', options: ['By removing the need for a Product Backlog', 'By letting the Project Manager order the Product Backlog', 'By making the PO a committee of Sponsors', 'By providing business, user and corporate context so product decisions stay aligned with overall goals'], correct: 'By providing business, user and corporate context so product decisions stay aligned with overall goals', explain: 'AgilePM gives the PO the wider organisational context Scrum alone may lack (4.4).' },
      { id: 'F23Q17', topic: 'IN', q: 'Which of the following are the three Project Role domains in AgilePM?\n1. Value Ownership\n2. Solution Delivery\n3. Delivery Enablement\n4. Contract Enforcement', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The three domains are Value Ownership, Solution Delivery and Delivery Enablement (5.3).' },
      { id: 'F23Q18', topic: 'IN', q: 'Who is described as the Project Champion, committed to success and holding the project budget?', options: ['The Scrum Master', 'The Product Owner', 'The Process Advisor', 'The Business Sponsor'], correct: 'The Business Sponsor', explain: 'The Business Sponsor is the Project Champion and holds the budget (5.3).' },
      { id: 'F23Q19', topic: 'IN', q: 'Identify the missing words. The Business Visionary makes decisions about [ ? ].', options: ['how the project is managed day to day', 'the integrity of the technical architecture only', 'who facilitates the Daily Scrum', 'business-value-related matters'], correct: 'business-value-related matters', explain: 'BV = business value; SA = solution integrity; PM = how the project is managed (5.5).' },
      { id: 'F23Q20', topic: 'IN', q: 'Consider the statements about the Scrum Master in a scaled AgilePM setting.\n1. Together with the Project Manager, the Scrum Master is accountable for facilitating cross-team planning, refinement and review events\n2. A Scrum Master may effectively support up to three teams', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both the cross-team facilitation accountability and the \'up to three teams\' guidance are stated (5.3.6).' },
      { id: 'F23Q21', topic: 'IN', q: 'Which class of decisions sits with the Project Manager rather than the Visionary or Architect?', options: ['The Product Goal in place of the Product Owner', 'Whether a PBI meets the Definition of Done', 'The legal wording of every customer contract', 'How the project is managed'], correct: 'How the project is managed', explain: 'PM decisions are about managing the project; product and solution decisions sit elsewhere (5.5).' },
      { id: 'F23Q22', topic: 'IN', q: 'Advisor roles sit outside the Delivery Team circle. Which three titles does AgilePM name?\n1. Business Advisor\n2. Solution Advisor\n3. Financial Controller as a fourth mandatory Advisor\n4. Process Advisor', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three Advisor roles are Business, Solution and Process (5.4).' },
      { id: 'F23Q23', topic: 'IN', q: 'Stakeholder issues and risks need a clear owner. Who holds that ownership, with Project Manager support?', options: ['The Project Manager alone, without Product Owner involvement', 'The Developers during the Daily Scrum', 'The Project Manager and Product Owner, with the PM supporting regular engagement', 'External regulators only'], correct: 'The Project Manager and Product Owner, with the PM supporting regular engagement', explain: 'PM and PO own stakeholder issues/risks; the PM supports timely communication with governance authorities (5.5).' },
      { id: 'F23Q24', topic: 'CC', q: 'Which pair of AgilePM principles is primarily about people working together and keeping information flowing?', options: ['Never Compromise Quality and Deliver on Time', 'Focus on the Business Need and Demonstrate Control', 'Collaborate and Communicate Continuously and Clearly', 'Build Incrementally and Develop Iteratively'], correct: 'Collaborate and Communicate Continuously and Clearly', explain: 'Principles 3 and 7 are the collaboration and communication pair (6.1).' },
      { id: 'F23Q25', topic: 'CC', q: 'Identify the missing word. Over-using technology for communication can reduce effectiveness because email or chat lack [ ? ] and tone of voice.', options: ['story points', 'MoSCoW codes', 'body language', 'RACI letters'], correct: 'body language', explain: 'Replacing face-to-face with email/chat loses body language and tone (6.3).' },
      { id: 'F23Q26', topic: 'CC', q: 'Consider the statements about a Facilitated Workshop.\n1. It has a workshop owner with a clear goal and an independent facilitator\n2. The facilitator is typically a Process Advisor who keeps the group focused and ensures everyone contributes', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Workshops need owner, selected participants and an independent Process Advisor facilitator (6.4).' },
      { id: 'F23Q27', topic: 'CC', q: 'Which of the following are communication choices AgilePM describes?\n1. Face-to-face conversation\n2. Instant messaging\n3. Email used as the primary method instead of confirmation\n4. Collaborative workspaces', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Email is a choice but is best for confirmation, not as the primary method — statement 3 is the failure mode (6.3).' },
      { id: 'F23Q28', topic: 'PR', q: 'What is a Solution Increment in AgilePM?', options: ['Only the code compiled by one Developer', 'A synonym for the Sprint Goal', 'A stepwise refinement of the overall solution that meets the agreed Definition of Done and may include multiple products plus other deliverables', 'The Terms of Reference after Pre-Project'], correct: 'A stepwise refinement of the overall solution that meets the agreed Definition of Done and may include multiple products plus other deliverables', explain: 'Solution Increments combine products with training, change, communications, etc. (7.1).' },
      { id: 'F23Q29', topic: 'PR', q: 'Which of the following are true about the Foundations Phase?\n1. It focuses on value, solution and process\n2. Fine details are left for the Delivery Phase\n3. Every requirement must be fully specified before the phase can end\n4. By the end there should be a high-level Delivery Plan for the next Project Increment', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Foundations stays relatively high-level; full specification waits for Delivery (7.4).' },
      { id: 'F23Q30', topic: 'PR', q: 'Identify the missing words. Incremental delivery of value is first explored in Feasibility and should be confirmed by the end of [ ? ].', options: ['the Foundations Phase', 'Pre-Project', 'Realisation only', 'the first Daily Scrum'], correct: 'the Foundations Phase', explain: 'Whether the solution can be delivered incrementally is confirmed by the end of Foundations (7.2).' },
      { id: 'F23Q31', topic: 'PR', q: 'Consider the statements about subsequent passes through Foundations.\n1. They help reduce risk by keeping early planning flexible\n2. They help avoid unnecessary complexity caused by VUCA', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Revisiting Foundations between increments keeps planning flexible and reduces VUCA-driven complexity (7.4, 10.2.3.11).' },
      { id: 'F23Q32', topic: 'PR', q: 'Which artifact is a milestone summary of key Feasibility findings for governance?', options: ['The Feasibility Assessment', 'The Sprint Backlog', 'The Daily Scrum notes', 'The Product Increment'], correct: 'The Feasibility Assessment', explain: 'The Feasibility Assessment is a milestone snapshot used for the go/no-go decision (7.3, Appendix A).' },
      { id: 'F23Q33', topic: 'ES', q: 'Identify the missing words. Acceptance Criteria answer the question of how we know the story fulfils the user\'s need, provides the functionality and [ ? ].', options: ['delivers the intended benefit', 'matches the original Gantt chart', 'has been estimated by the Project Manager', 'is a Won\'t Have'], correct: 'delivers the intended benefit', explain: 'AC confirm As a / I want / So that — need, functionality and benefit (8.2.3).' },
      { id: 'F23Q34', topic: 'ES', q: 'When do backlog items usually become fine-grained User Stories that a team can develop in a Sprint?', options: ['Product Backlog refinement and Sprint Planning in Delivery', 'Pre-Project conversation only', 'The Project Sprint Retrospective', 'Benefits Assessment after retirement'], correct: 'Product Backlog refinement and Sprint Planning in Delivery', explain: 'Fine-grained stories emerge in Delivery through refinement and Sprint Planning (8.2.4).' },
      { id: 'F23Q35', topic: 'ES', q: 'Which of the following are true about a change in the depth of a requirement?\n1. It does not change project scope and should be handled using MoSCoW contingency\n2. It is the same as scope creep (a change in breadth)\n3. Emerging detail within an agreed requirement is expected\n4. MoSCoW contingency planned in Foundations is the intended buffer', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Depth ≠ breadth/scope creep; depth uses MoSCoW contingency (8.2.4).' },
      { id: 'F23Q36', topic: 'ES', q: 'Consider the statements about Story Points.\n1. They estimate effort and allow people of different skill levels to participate equally\n2. They must always be converted to hours before they are valid', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Points deliberately avoid hour-blame dynamics; they are relative effort, not a mandatory hour conversion (Appendix C).' },
      { id: 'F23Q37', topic: 'ES', q: 'Which requirements constitute the Minimum Useable Subset that a timebox must deliver to succeed?', options: ['The Must Have requirements that must be delivered in the timebox for success', 'All Could Haves', 'Every item ever listed on the Solution Backlog', 'Won\'t Haves held for a later product'], correct: 'The Must Have requirements that must be delivered in the timebox for success', explain: 'MUST = Must Haves for that timeframe (9.2.1).' },
      { id: 'F23Q38', topic: 'ES', q: 'To avoid inflated Must Haves, AgilePM suggests initially classifying every requirement as which priority, promoting only with justification?', options: ['Won\'t Haves', 'Must Haves', 'Should Haves', 'Could Haves'], correct: 'Won\'t Haves', explain: 'Start as Won\'t Have and promote only with strong justification (9.8.1).' },
      { id: 'F23Q39', topic: 'PC', q: 'Which list correctly states AgilePM\'s four tracking and control concepts?', options: ['Outcome-based measurement, transparency of process and progress, responding to change, and management by exception', 'Outcome-based planning, planning to sensible horizons, plan/re-plan, and MoSCoW', 'Daily Scrum, vacation planning, Gantt baseline, and earned value only', 'Card, Conversation, Confirmation, and Context'], correct: 'Outcome-based measurement, transparency of process and progress, responding to change, and management by exception', explain: 'Do not confuse the four control concepts with the three planning concepts (10.1).' },
      { id: 'F23Q40', topic: 'PC', q: 'Consider the statements about who handles exceptions.\n1. In basic Scrum, the Product Owner handles exceptions\n2. In AgilePM, the Project Manager is involved when issues affect the broader project, collaborating with the Product Owner and, if appropriate, the Business Visionary', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'MbE scales from PO (team) to PM + PO/BV (project) (10.4.2).' },
      { id: 'F23Q41', topic: 'PC', q: 'Which of the following correctly describe the Project Sprint Review?\n1. It is a joint review with Delivery Teams represented\n2. Its spirit is inspect-and-adapt, not grilling teams on whether they met the Sprint Goal\n3. The Business Sponsor must personally demonstrate every Product Increment\n4. The Project Manager may facilitate overall, working with Scrum Masters and Product Owners as co-facilitators', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The BV often reviews vision/goals; the Sponsor is not required to demo every increment (10.2.3.7).' },
      { id: 'F23Q42', topic: 'PC', q: 'Identify the missing words. After team Sprint Retrospectives, the Project Sprint Retrospective is a joint event for the Project Organisation except [ ? ].', options: ['the Business Sponsor and Business Visionary', 'the Scrum Masters', 'the Project Manager', 'the Developers'], correct: 'the Business Sponsor and Business Visionary', explain: 'BS and BV are excluded from the Project Sprint Retrospective (10.2.3.8).' },
      { id: 'F23Q43', topic: 'PC', q: 'Specialist tools are only available in certain Sprints. At which planning horizon should that constraint typically be agreed?', options: ['During Foundations, as part of planning to sensible horizons for the next increment', 'During each Daily Scrum as a standing agenda item called vacation and logistics', 'Only after Deployment', 'Never — specialists must always be available'], correct: 'During Foundations, as part of planning to sensible horizons for the next increment', explain: 'Specialist/tool availability is medium-term Foundations/increment planning, not Daily Scrum content (10.2.2–10.2.3).' },
      { id: 'F23Q44', topic: 'RK', q: 'Who is responsible for identifying and owning Delivery Enablement risk, including organisation, schedule and dependencies?', options: ['The Business Visionary', 'The Project Manager', 'The Solution Architect', 'The Product Owner alone'], correct: 'The Project Manager', explain: 'BV owns value risk, SA owns solution-delivery risk, PM owns delivery-enablement risk (11.1).' },
      { id: 'F23Q45', topic: 'RK', q: 'Which of the following are true about using the PAQ?\n1. It is first typically used in Feasibility\n2. Disagreement with a statement indicates a risk that needs tailoring and mitigation\n3. It replaces MoSCoW as the only control on scope\n4. It should be reviewed at the end of Foundations', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'PAQ diagnoses approach risk; it does not replace MoSCoW (11.2).' },
      { id: 'F23Q46', topic: 'RK', q: 'Consider the statements about agility in practice and risk.\n1. How much of AgilePM\'s guidance is followed, and to what extent, influences the approach\'s intrinsic ability to deal with risk\n2. Following none of the guidance still gives the same risk resilience as full application', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Agility in practice is a key exception: weak application weakens risk handling (11.1).' },
      { id: 'F23Q47', topic: 'GV', q: 'Identify the missing words. AgilePM recommends giving [ ? ], not single figures, when estimating.', options: ['story-point league tables', 'ranges', 'unsigned verbal guesses only', 'fixed-price quotes from Feasibility'], correct: 'ranges', explain: 'Cone of Uncertainty: give ranges; the Sponsor picks any single figure (12.3.1).' },
      { id: 'F23Q48', topic: 'GV', q: 'Who is Responsible and who is Accountable for the Product Backlog?', options: ['Responsible: Developers; Accountable: Scrum Master', 'Responsible: Product Owner; Accountable: Business Visionary', 'Responsible: Project Manager; Accountable: Business Sponsor', 'Responsible: Solution Architect; Accountable: Product Owner'], correct: 'Responsible: Product Owner; Accountable: Business Visionary', explain: 'Product Backlog R = PO, A = BV (Appendix A).' },
      { id: 'F23Q49', topic: 'GV', q: 'Which of the following artifacts can be customised to show regulatory compliance?\n1. Solution Architecture Definition\n2. Sprint Review Records\n3. Project Review Reports\n4. The Daily Scrum itself, with no supporting record', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'SAD, Sprint Review Records and Project Review Reports can be tailored as evidence; the event alone is not an artifact (12.2).' },
      { id: 'F23Q50', topic: 'GV', q: 'Consider the statements about when Delivery Teams can give more solid estimates.\n1. Only after the Foundations Phase can Delivery Teams give more solid estimates\n2. Before Foundations, all estimates are rough indicators', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Solid estimates wait until after Foundations; earlier figures are rough (12.3.1).' },
    ],
  },
  {
    id: 'final24',
    title: 'Final Paper 24',
    questions: [
      { id: 'F24Q1', topic: 'KC', q: 'Identify the missing word. Volatility in VUCA means things change [ ? ] and unpredictably.', options: ['slowly', 'never', 'only after Deployment', 'quickly'], correct: 'quickly', explain: 'Volatility = things change quickly and unpredictably (2.1.2).' },
      { id: 'F24Q2', topic: 'KC', q: 'What is latent value?', options: ['Value already fully realised in a document', 'The contingency hidden in Could Haves', 'The difference between Must and Should', 'The potential value of a product, only realised when the product is actually in use'], correct: 'The potential value of a product, only realised when the product is actually in use', explain: 'Latent value is potential until the product is used; a solution-focused view captures it (2.2).' },
      { id: 'F24Q3', topic: 'KC', q: 'Which of the following are reasons projects are used as a delivery mechanism?\n1. To provide focus and coordination\n2. To control investment and resources\n3. To guarantee that VUCA will disappear\n4. To create a time-bound outcome within parameters', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Projects do not remove VUCA; they focus work and control investment (2.3).' },
      { id: 'F24Q4', topic: 'KC', q: 'Consider the statements about iterative versus incremental advantages.\n1. Iterative working tests assumptions early and lets the right solution emerge\n2. Incremental delivery lets the organisation gain value early and strengthens the business case as benefits are seen', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both advantages are stated; they are complementary (2.4.2).' },
      { id: 'F24Q5', topic: 'KC', q: 'For which kind of work does AgilePM say Scrum is a poorer fit?', options: ['Complex product work where the solution is not fully known', 'Collaborative R&D', 'Content creation with emerging requirements', 'Standardised or highly repetitive tasks that are already well defined, such as routine manufacturing'], correct: 'Standardised or highly repetitive tasks that are already well defined, such as routine manufacturing', explain: 'Scrum fits complex, uncertain collaborative work — not routine, well-defined repetitive tasks (2.2).' },
      { id: 'F24Q6', topic: 'SC', q: 'Which of the following correctly describe the Daily Scrum?\n1. It is a 15-minute event for the Developers\n2. It is held at the same time and place every working day\n3. Its purpose is to inspect progress toward the Sprint Goal and adapt the Sprint Backlog\n4. It is the only time Developers are allowed to adjust their plan', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Developers often meet throughout the day; the Daily Scrum is not their only planning window (3.5).' },
      { id: 'F24Q7', topic: 'SC', q: 'How does Scrum define the Increment that the team produces toward the Product Goal?', options: ['A Gantt chart of remaining hours', 'The same as the Solution Architecture Definition', 'A list of Won\'t Haves', 'A concrete stepping stone toward the Product Goal that is additive and must be usable'], correct: 'A concrete stepping stone toward the Product Goal that is additive and must be usable', explain: 'Each Increment is additive, verified and usable (3.6).' },
      { id: 'F24Q8', topic: 'SC', q: 'Besides individuals, interactions, processes and tools, what else does the Scrum Team inspect in the Sprint Retrospective?', options: ['The investment-board minutes', 'The Business Sponsor\'s diary', 'The PAQ scoring scale', 'The Definition of Done'], correct: 'The Definition of Done', explain: 'The Retro inspects individuals, interactions, processes, tools and the Definition of Done; max 3 hours for a one-month Sprint (3.5).' },
      { id: 'F24Q9', topic: 'SC', q: 'Identify the missing words. Schwaber and Sutherland describe Scrum as lightweight, simple to understand, and difficult to [ ? ].', options: ['document', 'timebox', 'fund', 'master'], correct: 'master', explain: 'Lightweight, simple to understand, difficult to master (3.1).' },
      { id: 'F24Q10', topic: 'SC', q: 'Which of the following are inputs typically used in Sprint Planning?\n1. The Product Backlog\n2. The latest Product Increment\n3. The finished Sprint Backlog from this Sprint, created before Planning starts\n4. Past performance of the Scrum Team', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Sprint Backlog is an output of Planning, not an input (3.5).' },
      { id: 'F24Q11', topic: 'SC', q: 'When is a Product Increment born?', options: ['When a stakeholder first mentions an idea', 'When the Project Manager updates the Delivery Plan', 'When the PAQ is first completed', 'The moment a Product Backlog item meets the Definition of Done'], correct: 'The moment a Product Backlog item meets the Definition of Done', explain: 'An Increment is born when a PBI meets the DoD (3.6).' },
      { id: 'F24Q12', topic: 'AF', q: 'What does common sense mean in the AgilePM ethos?', options: ['Adding a process for every exception', 'Treating the eight principles as optional slogans', 'Fixing features and flexing quality', 'Using logical thinking and practical judgement instead of introducing unnecessary complexity'], correct: 'Using logical thinking and practical judgement instead of introducing unnecessary complexity', explain: 'Common sense avoids unnecessary complexity; pragmatism adapts to real life (4.1).' },
      { id: 'F24Q13', topic: 'AF', q: 'Identify the missing words. AgilePM\'s philosophy statement says best value emerges when projects are aligned to [ ? ], with frequent delivery and motivated, empowered collaborators.', options: ['the longest possible Gantt chart', 'the auditor\'s template set', 'a single-figure estimate from Pre-Project', 'clear goals'], correct: 'clear goals', explain: 'Philosophy: aligned to clear goals, frequent delivery, motivated empowered people (4.1).' },
      { id: 'F24Q14', topic: 'AF', q: 'Which of the following are true about Never Compromise Quality?\n1. Expected quality is defined at the beginning of the project\n2. The Solution Architect is responsible for setting the Definition of Done\n3. Quality may be flexed if a deadline is near\n4. Business Visionary, Solution Architect, Product Owner and appropriate stakeholders provide quality oversight', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Quality is a fixed variable; it is not flexed to hit a date (4.2–4.3).' },
      { id: 'F24Q15', topic: 'AF', q: 'Consider the statements about Build Incrementally from Firm Foundations.\n1. Strong foundations for the solution and ways of working are created before major development\n2. Teams should gain an early high-level understanding of the business problem, the proposed solution and associated risk', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both the firm-foundations idea and the three early understandings are principle 5 (4.3).' },
      { id: 'F24Q16', topic: 'AF', q: 'Under which three conditions should documentation be created, according to Communicate Continuously and Clearly?', options: ['Whenever a template exists, at the end of every hour, and to occupy spare time', 'Only after Realisation, and only as a novel', 'Never, because AgilePM forbids documents', 'If it adds value to organisational or user understanding, helps development and support, or is essential for safety-critical or regulatory compliance'], correct: 'If it adds value to organisational or user understanding, helps development and support, or is essential for safety-critical or regulatory compliance', explain: 'Those three conditions gate documentation (4.3).' },
      { id: 'F24Q17', topic: 'IN', q: 'Consider these two claims about how agile leaders operate.\n1. Agile leaders develop new leaders, not followers\n2. Agile leaders must always take the direct, command-and-control decision themselves', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Leaders develop others and do not always take the direct approach (5.1).' },
      { id: 'F24Q18', topic: 'IN', q: 'What does the Business Visionary remain accountable for even if Product Backlog work is delegated?', options: ['Facilitating the Daily Scrum', 'Story-point estimates', 'Holding the entire project budget instead of the Sponsor', 'The Product Backlogs — accountability is not delegated away'], correct: 'The Product Backlogs — accountability is not delegated away', explain: 'BV may delegate backlog work but remains accountable (5.3).' },
      { id: 'F24Q19', topic: 'IN', q: 'Which of the following are Solution Architect accountabilities?\n1. Owning the solution architecture and delivery approach\n2. Ensuring regulatory or quality standards are reflected in the Definition of Done\n3. Ordering the Product Backlog instead of the Product Owner\n4. Providing guidance across Delivery Teams for a coherent solution', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The PO orders the Product Backlog; the SA owns architecture, DoD quality and cross-team coherence (5.3).' },
      { id: 'F24Q20', topic: 'IN', q: 'Identify the missing words. True leadership, per the Scrum Guide, defines success by the [ ? ] of the Delivery Team(s).', options: ['timesheet compliance', 'document count', 'Sponsor\'s seniority', 'effectiveness'], correct: 'effectiveness', explain: 'Success is the effectiveness of the team(s), developed through others (5.3.6).' },
      { id: 'F24Q21', topic: 'IN', q: 'In AgilePM, who is included in the title Developer?', options: ['Only software programmers', 'Only the Solution Architect', 'Anyone in the Scrum Team working Sprint Backlog tasks to help build a usable Product Increment', 'Only the Business Analyst if they sit outside the team'], correct: 'Anyone in the Scrum Team working Sprint Backlog tasks to help build a usable Product Increment', explain: 'Developer is inclusive and simplifies a cross-functional mix of skills (5.4).' },
      { id: 'F24Q22', topic: 'IN', q: 'Consider the statements about Business Advisors.\n1. They provide specialist business input on requirements, decisions and regulatory compliance\n2. A person may fulfil the role in Feasibility and later become a Product Owner or Business Ambassador', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both the specialist input and the later-role path are described (5.4).' },
      { id: 'F24Q23', topic: 'IN', q: 'Which of the Project Manager\'s relationships is with the person who establishes Scrum in the team?', options: ['Business Sponsor', 'External regulator only', 'Scrum Master', 'Investment board only'], correct: 'Scrum Master', explain: 'The PM\'s six relationships include the Scrum Master (Team Leader) (5.5).' },
      { id: 'F24Q24', topic: 'CC', q: 'Identify the missing Scrum Value. Team members have the confidence to do the right thing and tackle difficult problems: [ ? ].', options: ['Documentation', 'Hierarchy', 'Courage', 'Secrecy'], correct: 'Courage', explain: 'Courage is the Scrum Value of doing the right thing and tackling hard problems (6.1).' },
      { id: 'F24Q25', topic: 'CC', q: 'Which of the following correctly describe Team Collaboration?\n1. Members understand each other\'s skills and availability\n2. The team shares responsibility for difficulties and celebrates success equally\n3. Each person works only to personal KPIs and hides problems\n4. People support each other when needed', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Hiding problems and purely personal KPIs undermine team collaboration (6.2).' },
      { id: 'F24Q26', topic: 'CC', q: 'Which description matches Modelling as an AgilePM practice?', options: ['A substitute for the Definition of Done', 'A financial model that replaces the Business Case', 'A method of visually representing a problem or solution', 'A RACI letter meaning \'Monitor\''], correct: 'A method of visually representing a problem or solution', explain: 'Modelling makes the invisible visible, or provides a scaled/pattern representation (6.4).' },
      { id: 'F24Q27', topic: 'CC', q: 'Consider the statements about face-to-face communication.\n1. It is the most effective way to communicate in small or medium groups\n2. It allows body language and tone of voice to make communication richer', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Manifesto principle 6 and AgilePM communication choices agree (6.3).' },
      { id: 'F24Q28', topic: 'PR', q: 'Which of the following are phases of the AgilePM Process Model?\n1. Pre-Project\n2. Feasibility\n3. Waterfall Design Sign-off as a mandatory seventh phase\n4. Realisation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The six phases are Pre-Project, Feasibility, Foundations, Delivery, Deployment, Realisation (7.2).' },
      { id: 'F24Q29', topic: 'PR', q: 'How complete should the Business Case be by the end of Feasibility?', options: ['A fully baselined 200-page specification', 'A replacement for the Product Backlog', 'Outlined, simple and high-level, adding immediate value to communication or governance', 'Frozen so it cannot evolve in Foundations'], correct: 'Outlined, simple and high-level, adding immediate value to communication or governance', explain: 'Feasibility Business Case is evolutionary, simple and high-level (7.3).' },
      { id: 'F24Q30', topic: 'PR', q: 'Consider the statements about the Delivery Phase.\n1. It should aim to deliver a usable Product Increment each Sprint\n2. Delivering only a horizontal technology layer is discouraged because the increment is not yet usable', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Vertical Done slices each Sprint; horizontal layers delay value and integration (7.5).' },
      { id: 'F24Q31', topic: 'PR', q: 'Identify the missing words. AgilePM follows the principle that artifacts should only be created if they add real [ ? ].', options: ['value', 'pages', 'signatures', 'latency'], correct: 'value', explain: 'Create artifacts only if they add real value and aid shared understanding (7.2).' },
      { id: 'F24Q32', topic: 'PR', q: 'Who embeds the solution so that benefits can be realised, and who is accountable for wider business change?', options: ['Operational users and the organisation embed; the Business Visionary is accountable for wider business change and benefits realisation', 'The Scrum Master embeds; Developers are accountable for business change', 'The PAQ facilitator embeds; the auditor is accountable', 'No one — Realisation is optional theatre'], correct: 'Operational users and the organisation embed; the Business Visionary is accountable for wider business change and benefits realisation', explain: 'BV is accountable for wider business change and subsequent benefits realisation (7.7, 10.2.3.10).' },
      { id: 'F24Q33', topic: 'ES', q: 'What does INVEST\'s Small (Enough) criterion mean?', options: ['The story is manageable within a specific timebox — project, increment or Sprint', 'The story must be fewer than five words', 'The story is too small to estimate', 'The story can only describe a user-interface colour'], correct: 'The story is manageable within a specific timebox — project, increment or Sprint', explain: 'Small enough for the relevant timebox (8.2.3.4).' },
      { id: 'F24Q34', topic: 'ES', q: 'Which of the following are suggested Definition of Ready criteria?\n1. Clearly defined outcome and scope\n2. Value identified and aligned with the Product Goal\n3. The item is guaranteed to be a Must Have at project level\n4. Acceptance Criteria are agreed', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'DoR does not require a project-level Must; it is about readiness for a Sprint (8.2.3.5).' },
      { id: 'F24Q35', topic: 'ES', q: 'Identify the missing word. Estimating by analogy is also known as [ ? ] estimating.', options: ['comparative', 'bottom-up', 'commitment-free', 'absolute-hour'], correct: 'comparative', explain: 'Analogy = comparative estimating (8.3.3).' },
      { id: 'F24Q36', topic: 'ES', q: 'Consider the statements about MoSCoW and timeframes.\n1. MoSCoW is only effective when used together with a specified timeframe\n2. A requirement\'s priority at Project Increment level may differ from its priority at project level', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'MoSCoW needs a timebox; priorities can differ by horizon (9.1, 9.3).' },
      { id: 'F24Q37', topic: 'ES', q: 'If every requirement is labelled Must Have, what is the usual consequence for control of the timebox?', options: ['There is no lower-priority buffer, so flexibility to stay on time and budget is lost', 'MoSCoW becomes more powerful', 'Could Haves automatically appear', 'Velocity doubles'], correct: 'There is no lower-priority buffer, so flexibility to stay on time and budget is lost', explain: 'All-Must means MoSCoW is ineffective — often because items were not broken down (9.8).' },
      { id: 'F24Q38', topic: 'ES', q: 'Which statements correctly describe how estimates should behave across the lifecycle?\n1. Estimates become more precise as requirements become clearer\n2. Estimates are not fixed; they evolve as information emerges\n3. Feasibility estimates are rough and based on limited information\n4. Once made in Feasibility, estimates must never be changed', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The cycle updates estimates; they are not frozen after Feasibility (8.3.4).' },
      { id: 'F24Q39', topic: 'PC', q: 'Which of the following correctly describe planning to sensible horizons?\n1. Long-term planning covers the project and post-project activities\n2. Medium-term planning focuses on the next Project Increment or upcoming series of Sprints\n3. Short-term planning is managed by Sprint Planning toward the Sprint Goal\n4. The Daily Scrum is the correct horizon for agreeing next-quarter vacation plans', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Vacation/absence cover is not a Daily Scrum purpose; use a sensible longer horizon (10.2.2).' },
      { id: 'F24Q40', topic: 'PC', q: 'Why does AgilePM use Management by Exception as a control concept?', options: ['Decision-makers focus on critical issues while Delivery Teams handle day-to-day challenges independently', 'Every issue is escalated so Project Roles stay busy', 'The Sprint Goal is abandoned whenever a task slips', 'The Business Sponsor attends every Daily Scrum'], correct: 'Decision-makers focus on critical issues while Delivery Teams handle day-to-day challenges independently', explain: 'MbE reduces unnecessary oversight and keeps the project fast but controlled (10.4.2).' },
      { id: 'F24Q41', topic: 'PC', q: 'Identify the missing words. The output of Delivery Team Sprint Planning is a [ ? ] for each Delivery Team.', options: ['Sprint Backlog', 'Business Case', 'Terms of Reference', 'Benefits Assessment'], correct: 'Sprint Backlog', explain: 'Team planning (Topic 3 / How) produces each team\'s Sprint Backlog; the PM then updates the Delivery Plan (10.2.3.4).' },
      { id: 'F24Q42', topic: 'PC', q: 'Consider the statements about burn-down and burn-up charts.\n1. Their primary purpose is inspection and adaptation — visibility for the team\n2. They should be used to judge and compare team performance across the organisation', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Charts are working tools, not performance league tables (10.2.3.5).' },
      { id: 'F24Q43', topic: 'PC', q: 'In Project Sprint Planning Topic 2, who pulls the PBIs they forecast they can collectively get Done?', options: ['The Developers in the Delivery Team(s)', 'The Business Sponsor', 'The auditor', 'External customers only'], correct: 'The Developers in the Delivery Team(s)', explain: 'Developers pull and split PBIs; Scrum Masters typically facilitate the split (10.2.3.4).' },
      { id: 'F24Q44', topic: 'RK', q: 'Consider the statements about when a separate formal risk process is needed.\n1. Day-to-day AgilePM activities usually mean no separate formal risk process is required\n2. Highly regulated or safety-related contexts may still need an intentional risk-management process, reflected in MAD, SAD and DAD', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Integrated by default; extra process is the regulated/safety exception (11.1, 11.3).' },
      { id: 'F24Q45', topic: 'RK', q: 'If the PAQ shows the project lacks a clear vision, what is a typical remedy?', options: ['Cancel MoSCoW permanently', 'Ask the Business Visionary to define and share a clear vision with everyone involved', 'Wait until Realisation to write a vision', 'Replace the Product Owner with a committee'], correct: 'Ask the Business Visionary to define and share a clear vision with everyone involved', explain: 'Unclear vision is often quickly fixed by the BV explaining and sharing it (11.2.2 Statement 3).' },
      { id: 'F24Q46', topic: 'RK', q: 'Which of the following correctly describe PAQ disagreement handling?\n1. If any statement is considered not true, it indicates a risk to using AgilePM successfully\n2. Some risks are fixed with simple actions; others need approach adjustments\n3. Using AgilePM without adjustments is recommended even when difficult risks remain unresolved\n4. Tailoring the approach is an important part of Foundations', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Unresolved difficult risks mean using default AgilePM without adjustment is not recommended (11.2.1).' },
      { id: 'F24Q47', topic: 'GV', q: 'Who is Responsible and who is Accountable for the Management Approach Definition (MAD)?', options: ['Responsible: Solution Architect; Accountable: Business Visionary', 'Responsible: Project Manager; Accountable: Business Sponsor', 'Responsible: Product Owner; Accountable: Developers', 'Responsible: Scrum Master; Accountable: Product Owner'], correct: 'Responsible: Project Manager; Accountable: Business Sponsor', explain: 'MAD R = PM, A = BS; it is baselined at the end of Foundations (Appendix A).' },
      { id: 'F24Q48', topic: 'GV', q: 'Identify the missing words. In agile environments, financial governance can feel controversial because it may conflict with agile [ ? ] or feel like overhead.', options: ['Sprints', 'principles', 'User Story cards', 'Daily Scrums'], correct: 'principles', explain: 'Responsible organisations still need investment decisions; ranges and MoSCoW keep finance aligned (12.3.1).' },
      { id: 'F24Q49', topic: 'GV', q: 'In financial governance, when is a Foundations Summary particularly useful?', options: ['To replace the Daily Scrum', 'As a shorter version of the Business Case when the full document is not needed', 'To record vacation plans', 'To cancel the Cone of Uncertainty'], correct: 'As a shorter version of the Business Case when the full document is not needed', explain: 'Foundations Summary is a shorter/snapshot view for governance (12.3.2).' },
      { id: 'F24Q50', topic: 'GV', q: 'Consider the statements about compliance experts in the Project Team.\n1. They should make sure necessary records are created, kept lightweight, accurate, signed and stored for audit\n2. They should first understand what the regulation is trying to achieve, then meet that goal in an agile way', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Understand the intent, then comply with agile evidence — not cargo-cult documents (12.2).' },
    ],
  },
  {
    id: 'final25',
    title: 'Final Paper 25',
    questions: [
      { id: 'F25Q1', topic: 'KC', q: 'How is Business Agility achieved, according to the Agile Business Consortium?', options: ['By replacing all people with automated workflows', 'By fixing scope and varying quality', 'By banning facilitated workshops', 'By inspiring, enabling and harnessing collaborative and creative ways of working to meet the organisation\'s core purpose'], correct: 'By inspiring, enabling and harnessing collaborative and creative ways of working to meet the organisation\'s core purpose', explain: 'ABC: inspire, enable and harness collaborative and creative ways of working (2.1.1).' },
      { id: 'F25Q2', topic: 'KC', q: 'In the VUCA acronym, what does Uncertainty specifically mean?', options: ['Information or situations can have more than one possible meaning', 'Things change quickly and unpredictably', 'Cause and effect are no longer clear because parts are interconnected', 'It is hard to know what will happen or to make accurate predictions'], correct: 'It is hard to know what will happen or to make accurate predictions', explain: 'Uncertainty is unpredictability; Ambiguity is multiple meanings; Volatility is rapid change; Complexity is unclear cause and effect (2.1.2).' },
      { id: 'F25Q3', topic: 'KC', q: 'Identify the missing words. Individuals and interactions over processes and tools requires each person to be prepared to contribute, capable in their job, and [ ? ] to make decisions.', options: ['silent unless spoken to', 'replaced by a procedure', 'limited to reporting status', 'empowered (trusted, willing, authorised)'], correct: 'empowered (trusted, willing, authorised)', explain: 'The first value requires contribution, capability and empowerment (2.1.3).' },
      { id: 'F25Q4', topic: 'KC', q: 'AgilePM describes project management through several lenses. Which of the following belong?\n1. Who — people, teams and structures\n2. Why — purpose, value and business case\n3. When — timeframes, events and deliveries\n4. Whether Scrum events may be deleted to save time', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Who/Why/When/Where; Scrum\'s core elements are not deleted to \'save time\' (2.3, 3.1).' },
      { id: 'F25Q5', topic: 'KC', q: 'Why is product-management agility still valuable even on a relatively stable project?', options: ['It is not — agility only helps chaotic projects', 'It removes the need for any Business Case', 'It freezes requirements so VUCA cannot occur', 'It still improves communication, increases stakeholder involvement, supports better results and allows incremental benefits'], correct: 'It still improves communication, increases stakeholder involvement, supports better results and allows incremental benefits', explain: 'Agility helps even stable work via communication, involvement and incremental benefits (2.4.3).' },
      { id: 'F25Q6', topic: 'SC', q: 'Consider the statements about Transparency and Inspection.\n1. Transparency enables inspection; transparency without inspection is misleading and wasteful\n2. Inspection enables adaptation; inspection without adaptation is pointless', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The three pillars are linked: transparency → inspection → adaptation (3.2).' },
      { id: 'F25Q7', topic: 'SC', q: 'Which of the following are Developers\' accountabilities?\n1. Creating a plan for the Sprint (the Sprint Backlog)\n2. Instilling quality by adhering to the Definition of Done\n3. Owning the project budget\n4. Adapting their plan each day toward the Sprint Goal', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Budget sits with the Business Sponsor, not Developers (3.4, 5.3).' },
      { id: 'F25Q8', topic: 'SC', q: 'For a Sprint of one month, what is the longest permitted Sprint Review?', options: ['15 minutes', '3 hours', '8 hours', '4 hours'], correct: '4 hours', explain: 'Review max 4 hours for a one-month Sprint (3.5).' },
      { id: 'F25Q9', topic: 'SC', q: 'Identify the missing words. The Sprint Backlog is composed of the Sprint Goal (why), the selected Product Backlog items (what), and [ ? ] (how).', options: ['the Business Case', 'the Terms of Reference', 'the PAQ scores', 'an actionable plan for delivering the Product Increment'], correct: 'an actionable plan for delivering the Product Increment', explain: 'Sprint Backlog = why + what + how (3.6).' },
      { id: 'F25Q10', topic: 'SC', q: 'Which of the following correctly describe the Product Goal?\n1. It describes a future state of the product used as a planning target\n2. It is the long-term objective for the Scrum Team\n3. Several Product Goals should be active for the same product at once\n4. It must be fulfilled or abandoned before taking on the next Product Goal', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'One Product Goal at a time (3.6).' },
      { id: 'F25Q11', topic: 'SC', q: 'How does the Scrum Master serve the Product Owner?', options: ['By ordering the Product Backlog whenever the PO is busy', 'By cancelling Sprints on the PO\'s behalf as routine control', 'By estimating all PBIs so the PO need not talk to Developers', 'By helping with techniques for Product Goal definition, backlog management and empirical product planning, and by facilitating stakeholder collaboration'], correct: 'By helping with techniques for Product Goal definition, backlog management and empirical product planning, and by facilitating stakeholder collaboration', explain: 'The SM serves the PO with techniques and facilitation, not by taking over backlog ownership (3.4).' },
      { id: 'F25Q12', topic: 'AF', q: 'Identify the missing word. Parkinson\'s Law, as referenced in AgilePM, states that work expands to fill the [ ? ] available.', options: ['budget reserve', 'Product Backlog', 'team size', 'time'], correct: 'time', explain: 'Parkinson\'s Law: work expands to fill the time available (4.2).' },
      { id: 'F25Q13', topic: 'AF', q: 'Value Ownership roles must stay clear on which three facts throughout the project?', options: ['Only the colour of the Team Board', 'The Developers\' private estimates in hours', 'Which PAQ statement number is lucky', 'What will be delivered, when it will be delivered, and how much it will cost'], correct: 'What will be delivered, when it will be delivered, and how much it will cost', explain: 'What / when / how much — required understanding for Value Ownership (4.3).' },
      { id: 'F25Q14', topic: 'AF', q: 'Consider the statements about Develop Iteratively.\n1. Iterative development means working closely with customer/stakeholder to improve the solution using short cycles\n2. Frequent demonstrations, regular reviews, adjustments and embracing change support transparency, inspection, adaptation and evolution', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Principle 6 is iterative development with empirical loops (4.3).' },
      { id: 'F25Q15', topic: 'AF', q: 'Which of the following does AgilePM with Scrum offer?\n1. A project lifecycle with appropriate governance\n2. Additional roles ensuring value delivery based on organisational need\n3. A rule that Scrum events must be deleted on multi-team projects\n4. Techniques to help deliver on time and within budget', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'AgilePM adds lifecycle, roles and on-time techniques around Scrum; it does not delete Scrum events (4.4).' },
      { id: 'F25Q16', topic: 'AF', q: 'What communication path does AgilePM add that helps a Scrum Master obtain support for the team?', options: ['By making the SM accountable for the Business Case', 'By instructing the SM to manage and direct Developers', 'By removing Retrospectives', 'By giving a way to communicate with business leaders and project managers so teams get the support they need'], correct: 'By giving a way to communicate with business leaders and project managers so teams get the support they need', explain: 'AgilePM connects the SM to the wider project so team performance can be supported (4.4).' },
      { id: 'F25Q17', topic: 'IN', q: 'Which Agile Leadership principle is demonstrated by an active, visible leader who creates a vision for change and lends it credibility?', options: ['Emotion is a foundation for enhanced creativity and innovation', 'Organisations improve through effective feedback', 'People require meaning and purpose to make work fulfilling', 'Actions speak louder than words'], correct: 'Actions speak louder than words', explain: 'Visible, active role-modelling of the vision is \'Actions speak louder than words\' (5.1).' },
      { id: 'F25Q18', topic: 'IN', q: 'Which of the following are true about the Business Sponsor role?\n1. The role is fulfilled by a single person, who may represent a governing group in complex contexts\n2. Financial accountabilities may be governed by a higher authority such as an investment board\n3. The role is always shared equally among all Developers\n4. The Sponsor owns the project and empowers other Project Roles', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'One Sponsor (who may represent a board); not a role shared by all Developers (5.3).' },
      { id: 'F25Q19', topic: 'IN', q: 'Consider the statements about the Product Owner in AgilePM.\n1. Value ownership at team level may be fulfilled by a Business Ambassador in some organisations\n2. Changes to the Product Backlog must be made by influencing the Product Owner or Business Ambassador', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Both the Ambassador path and the \'influence the PO\' rule are AgilePM guidance (5.3.5).' },
      { id: 'F25Q20', topic: 'IN', q: 'Identify the missing words. AgilePM describes external stakeholders as [ ? ] who can still influence the work or be affected by the solution.', options: ['always only regulators', 'members of the Scrum Team', 'a fourth Scrum role', 'people external to the project'], correct: 'people external to the project', explain: 'They sit outside the project organisation yet may influence it or be affected by the solution (5.2).' },
      { id: 'F25Q21', topic: 'IN', q: 'What do Solution Advisors do?', options: ['Own the Business Case instead of the Sponsor', 'Facilitate the Project Sprint Retrospective as Business Sponsor', 'Provide specialist, perhaps technical, input on requirements, design and operational decisions, and support deployment and training', 'Order the Product Backlog'], correct: 'Provide specialist, perhaps technical, input on requirements, design and operational decisions, and support deployment and training', explain: 'Solution Advisors collaborate with solution-delivery roles (5.4).' },
      { id: 'F25Q22', topic: 'IN', q: 'Which of the following are among the Project Manager\'s six key relationships?\n1. Business Sponsor\n2. Business Visionary\n3. The Daily Scrum as a reporting line to the PM\n4. Product Owner', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Daily Scrum is for Developers, not a PM status meeting. Relationships include BS, BV, SA, PO, SM and other stakeholders (5.5).' },
      { id: 'F25Q23', topic: 'IN', q: 'Consider the statements about a Business Analyst in AgilePM.\n1. Like Scrum, AgilePM may recognise a Business Analyst as a Developer in some contexts\n2. Business Analysts may work at strategic level (shaping strategy) and operational level (detailed acceptance criteria)', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'BA as Developer, plus strategic and operational levels (5.4).' },
      { id: 'F25Q24', topic: 'CC', q: 'Consider the statements about documents versus shared understanding.\n1. The main goal of a document is shared understanding of its content\n2. A plan remains a plan even if it is not written down — most people do not write a formal plan for a short vacation', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Understanding beats paperwork; the vacation analogy is AgilePM\'s (6.4).' },
      { id: 'F25Q25', topic: 'CC', q: 'What should leaders focus on when mistakes happen in a collaborative team?', options: ['Blaming the individual publicly', 'Hiding the mistake from the Retrospective', 'Learning rather than blame, which strengthens trust', 'Escalating every mistake as an MbE exception to the Sponsor'], correct: 'Learning rather than blame, which strengthens trust', explain: 'Leaders encourage learning, not blame (6.2).' },
      { id: 'F25Q26', topic: 'CC', q: 'Which of the following is NOT a soft skill AgilePM lists as needed for collaboration?', options: ['Refusing to communicate except by formal contract', 'Empathy', 'Adaptability', 'Resilience'], correct: 'Refusing to communicate except by formal contract', explain: 'Soft skills include creativity, empathy, problem-solving, adaptability, reliability, resilience, leadership, teamwork and communication (6.1).' },
      { id: 'F25Q27', topic: 'CC', q: 'Identify the missing words. Each Scrum event and artifact has a clear role in AgilePM; if one element is removed, the system becomes weak, like a table losing a [ ? ].', options: ['leg', 'Sponsor', 'Must Have', 'range estimate'], correct: 'leg', explain: 'Scrum\'s events and artifacts are interconnected; remove one and the system weakens (6.4).' },
      { id: 'F25Q28', topic: 'PR', q: 'Identify the missing words. The terms Delivery Timebox and [ ? ] are used interchangeably in the AgilePM reference book.', options: ['Sprint', 'Project Increment Review', 'Pre-Project', 'Cone of Uncertainty'], correct: 'Sprint', explain: 'Delivery Timebox and Sprint are interchangeable terms (7.1).' },
      { id: 'F25Q29', topic: 'PR', q: 'Which of the following are true about a Solution in AgilePM?\n1. It includes products, services, processes and people as needed to meet the outcome\n2. It only ever consists of a single Product Increment from one team\n3. A Deployed Solution is what exists when a Solution Increment is in operational use\n4. Multiple Delivery Teams may work in parallel on different products that make up the solution', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'A solution is broader than one product increment (7.1).' },
      { id: 'F25Q30', topic: 'PR', q: 'What is the purpose of the Terms of Reference?', options: ['To present or share a new project idea and justify the need for a Feasibility Phase', 'To list every fine-grained User Story', 'To record Daily Scrum attendance', 'To replace the Definition of Done'], correct: 'To present or share a new project idea and justify the need for a Feasibility Phase', explain: 'ToR is a short milestone that justifies exploring Feasibility (7.3).' },
      { id: 'F25Q31', topic: 'PR', q: 'Consider the statements about the Management Approach Definition in Feasibility.\n1. The MAD is recommended in Feasibility and describes how the project will be organised and managed\n2. Training, mentoring or coaching needed should be planned for Foundations if the project is approved', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Outline MAD in Feasibility; capability-building is planned into Foundations (7.3).' },
      { id: 'F25Q32', topic: 'PR', q: 'Which subject matter is the main content of the Delivery Approach Definition?', options: ['How the project and delivery team(s) will build the solution, including tools, practices and quality assurance', 'The business vision statement only', 'The investment board\'s voting record', 'The Product Owner\'s personal objectives'], correct: 'How the project and delivery team(s) will build the solution, including tools, practices and quality assurance', explain: 'DAD = how we build and assure quality (7.3–7.4, Appendix A).' },
      { id: 'F25Q33', topic: 'ES', q: 'Consider the statements about User Story levels.\n1. Epic User Stories are typical in Feasibility — broad and high-level\n2. Fine-grained User Stories ready for a Sprint are typical of Delivery refinement', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Epic → User Story (Foundations) → fine-grained (Delivery) (8.2.3).' },
      { id: 'F25Q34', topic: 'ES', q: 'Who originated the widely used \'As a... I want... So that...\' format?', options: ['Rachel Davies', 'Barry Boehm', 'Frederick Taylor', 'Ken Schwaber alone'], correct: 'Rachel Davies', explain: 'Rachel Davies invented the widely used format in the early 2000s (8.2.3).' },
      { id: 'F25Q35', topic: 'ES', q: 'Which of the following are true about Could Haves?\n1. They are wanted or desirable but less important than Should Haves\n2. They act as a buffer providing the main pool of contingency\n3. They are guaranteed to be delivered\n4. AgilePM suggests allocating about 20% of total effort to them', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Coulds are not guaranteed (9.2.3).' },
      { id: 'F25Q36', topic: 'ES', q: 'Identify the missing word. Rather than [ ? ] more items to a poor standard, AgilePM prefers fewer higher-value outcomes.', options: ['outputting', 'timeboxing', 'facilitating', 'modelling'], correct: 'outputting', explain: 'Fewer higher-value outcomes over outputting more things substandardly (8.3.2).' },
      { id: 'F25Q37', topic: 'ES', q: 'Which role must see that MoSCoW priorities will deliver the return assumed in the Business Case?', options: ['The Business Visionary', 'The Scrum Master', 'The Process Advisor', 'The Developers during Planning Poker'], correct: 'The Business Visionary', explain: 'The BV ensures priorities deliver expected RoI (9.7).' },
      { id: 'F25Q38', topic: 'ES', q: 'Which of the following are true about Planning Poker?\n1. Cards are kept hidden until revealed so early opinions do not sway others\n2. The Project Manager observes but does not estimate or influence the Delivery Team\n3. The Project Manager assigns the official story-point value after the session\n4. The Scrum Master typically facilitates while Developers estimate', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The PM must not take over or assign estimates (Appendix C).' },
      { id: 'F25Q39', topic: 'PC', q: 'Identify the missing words. Outcome-based measurement tracks progress based on [ ? ], not just tasks completed.', options: ['delivered value', 'hours booked', 'emails sent', 'pages of minutes'], correct: 'delivered value', explain: 'Control concept: measure outcomes/value, not task counts (10.2.2, 10.4.1).' },
      { id: 'F25Q40', topic: 'PC', q: 'Which of the following correctly describe multi-team alignment activities?\n1. Cross-Team Refinement inspects Product Backlogs and may adapt Project Artifacts such as the Delivery Plan\n2. A Scrum of Scrums brings representatives together every few days, especially when dependencies exist\n3. The Daily Scrum should be extended to two hours so vacation planning can be completed\n4. CTR inputs typically include Scrum artifacts plus Business Case, goals, backlogs and Delivery Plan', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Do not turn the Daily Scrum into vacation planning (10.2.3.6).' },
      { id: 'F25Q41', topic: 'PC', q: 'Consider the statements about MoSCoW during Project Sprint Planning.\n1. In an AgilePM context MoSCoW is applied to the PBIs selected by each Delivery Team\n2. Those priorities may change during Delivery Team Sprint Planning as effort is estimated', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'MoSCoW is applied at selection and reviewed when the team plans How (10.2.3.4).' },
      { id: 'F25Q42', topic: 'PC', q: 'Who typically facilitates Project Sprint Planning?', options: ['The Agile Project Manager', 'The Business Sponsor', 'External customers only', 'The auditor'], correct: 'The Agile Project Manager', explain: 'The Agile PM facilitates; PO and team representatives attend (10.2.3.4.3).' },
      { id: 'F25Q43', topic: 'PC', q: 'Unfinished requirements should be reviewed at least when?', options: ['At the end of each Sprint and at the end of each Project Increment', 'Only when the project is cancelled', 'Once, during Pre-Project', 'Never, because priorities never change'], correct: 'At the end of each Sprint and at the end of each Project Increment', explain: 'Minimum review points for unfinished requirements (10.2.3.11).' },
      { id: 'F25Q44', topic: 'RK', q: 'Which of the following are true about VUCA-related risk in AgilePM?\n1. Risks may be internal or external to the Project Organisation and may challenge whether the Solution Goal remains valid\n2. Workshops in Feasibility and Foundations address risks early\n3. Risks are closed once and for all in Pre-Project, so later refinement ignores them\n4. Risks continue to be reviewed as part of backlog refinement', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Risk is ongoing because VUCA is ongoing (11.1).' },
      { id: 'F25Q45', topic: 'RK', q: 'Value-related risk has a named owner. Which role is that?', options: ['The Business Visionary', 'The Solution Architect', 'The Project Manager', 'The Scrum Master'], correct: 'The Business Visionary', explain: 'BV = value risk; SA = solution-delivery risk; PM = delivery-enablement risk (11.1).' },
      { id: 'F25Q46', topic: 'RK', q: 'Consider the statements about PAQ Statement 1 (understanding AgilePM and Scrum).\n1. Disagreement often means some people have not had appropriate training or briefings\n2. Suggested action includes training/briefings and, if needed, help from accredited trainers or experienced coaches', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Disagreement → train/brief/coach; that is tailoring/mitigation (11.2.2).' },
      { id: 'F25Q47', topic: 'GV', q: 'Who is Responsible and who is Accountable for the Solution Architecture Definition (SAD)?', options: ['Responsible: Project Manager; Accountable: Business Sponsor', 'Responsible: Solution Architect; Accountable: Business Visionary', 'Responsible: Product Owner; Accountable: Developers', 'Responsible: Scrum Master; Accountable: Product Owner'], correct: 'Responsible: Solution Architect; Accountable: Business Visionary', explain: 'SAD R = SA, A = BV (Appendix A).' },
      { id: 'F25Q48', topic: 'GV', q: 'Consider the statements about the two kinds of quality in a regulatory context.\n1. Solution quality is how well the delivered solution meets organisational needs\n2. Process quality is whether the work to build the solution was done in a controlled, demonstrable way', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Never Compromise Quality covers both solution and process quality (12.2).' },
      { id: 'F25Q49', topic: 'GV', q: 'Identify the missing words. An auditor might not recognise a User Story or Sprint Backlog as a valid plan unless it is [ ? ].', options: ['printed in a 200-page specification', 'explained clearly', 'signed by every Developer hourly', 'converted into story points by the Sponsor'], correct: 'explained clearly', explain: 'Help auditors understand what valid agile evidence looks like (12.2).' },
      { id: 'F25Q50', topic: 'GV', q: 'Which of the following are true about RACI on the Delivery Plan and DAD?\n1. Delivery Plan: Responsible and Accountable are both the Project Manager\n2. DAD: Responsible is the Solution Architect and Accountable is the Project Manager\n3. Delivery Plan: Accountable is always the Product Owner\n4. DAD explains tools, techniques, practices and the quality-assurance strategy', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Delivery Plan R/A = PM; DAD R = SA, A = PM (Appendix A).' },
    ],
  },
]
